5	@Observable
6	final class LogConsoleModel {
7	    static let capacities = [1000, 5000, 20000]
8	
9	    private(set) var entries: [LogEntry] = []
10	    private(set) var visible: [LogEntry] = []
11	    private(set) var pending: [LogEntry] = []
12	
13	    /// Pause freezes the display, never the stream — dropping lines here would punch a
14	    /// hole in the exported log exactly when the user is watching a failure.
15	    var paused = false {
16	        didSet {
17	            if !paused {
18	                flush()
19	            }
20	        }
21	    }
22	
23	    var capacity = 5000 {
24	        didSet {
25	            trim()
26	            recompute()
27	        }
28	    }
29	
30	    var query = "" {
31	        didSet { recompute() }
32	    }
33	
34	    var minimumLevel = LogLevel.debug {
35	        didSet { recompute() }
36	    }
37	
38	    private var nextID = 0
39	
40	    var isFiltered: Bool {
41	        !query.isEmpty || minimumLevel != .debug
42	    }
43	
44	    var copyText: String {
45	        visible.map(\.text).joined(separator: "\n")
46	    }
47	
48	    var filterSummary: String? {
49	        guard isFiltered else { return nil }
50	        var parts = ["level: \(minimumLevel)"]
51	        if !query.isEmpty {
52	            parts.append("search: \"\(query)\"")
53	        }
54	        return parts.joined(separator: ", ")
55	    }
56	
57	    func ingest(_ chunk: String) {
58	        let appended = chunk.split(separator: "\n", omittingEmptySubsequences: true).map { raw in
59	            defer { nextID += 1 }
60	            return LogEntry(id: nextID, raw: String(raw))
61	        }
62	        guard !appended.isEmpty else { return }
63	        if paused {
64	            pending.append(contentsOf: appended)
65	            return
66	        }
67	        entries.append(contentsOf: appended)
68	        trim()
69	        visible.append(contentsOf: appended.filter(matches))
70	        trimVisible()
71	    }
72	
73	    func clear() {
74	        entries = []
75	        visible = []
76	        pending = []
77	    }
78	
79	    func export(address: String) -> LogExport {
80	        LogExport(entries: visible, address: address, totalCount: entries.count, filterSummary: filterSummary)
81	    }
82	
83	    private func flush() {
84	        guard !pending.isEmpty else { return }
85	        entries.append(contentsOf: pending)
86	        visible.append(contentsOf: pending.filter(matches))
87	        pending = []
88	        trim()
89	        trimVisible()
90	    }
91	
92	    private func trim() {
93	        if entries.count > capacity {
94	            entries.removeFirst(entries.count - capacity)
95	        }
96	    }
97	
98	    /// `visible` is a maintained cache, so it must drop the same head `entries` dropped.
99	    private func trimVisible() {
100	        guard let oldest = entries.first?.id else {
101	            visible = []
102	            return
103	        }
104	        let drop = visible.prefix { $0.id < oldest }.count
105	        if drop > 0 {
106	            visible.removeFirst(drop)
107	        }
108	    }
109	
110	    private func matches(_ entry: LogEntry) -> Bool {
111	        entry.level >= minimumLevel && (query.isEmpty || entry.text.localizedCaseInsensitiveContains(query))
112	    }
113	
114	    private func recompute() {
115	        visible = entries.filter(matches)
116	    }
117	}
