3	/// Serves canned HTTP responses to a `URLSession` injected into `RobotConnection`,
4	/// which is the only way to exercise daemon status codes without a daemon.
5	final class StubURLProtocol: URLProtocol {
6	    struct Stub: Sendable {
7	        let statusCode: Int
8	        let body: Data
9	
10	        init(statusCode: Int, json: String = "{}") {
11	            self.statusCode = statusCode
12	            body = Data(json.utf8)
13	        }
14	    }
15	
16	    private nonisolated(unsafe) static var stubs: [String: Stub] = [:]
17	    private static let lock = NSLock()
18	
19	    /// Keyed by request path, e.g. `/api/state/full`.
20	    static func install(_ stubs: [String: Stub]) {
21	        lock.withLock { Self.stubs = stubs }
22	    }
23	
24	    static func reset() {
25	        lock.withLock { stubs = [:] }
26	    }
27	
28	    static func makeSession() -> URLSession {
29	        let configuration = URLSessionConfiguration.ephemeral
30	        configuration.protocolClasses = [StubURLProtocol.self]
31	        return URLSession(configuration: configuration)
32	    }
33	
34	    override static func canInit(with _: URLRequest) -> Bool {
35	        true
36	    }
37	
38	    override static func canonicalRequest(for request: URLRequest) -> URLRequest {
39	        request
40	    }
41	
42	    override func startLoading() {
43	        guard let url = request.url,
44	              let stub = Self.lock.withLock({ Self.stubs[url.path] }),
45	              let response = HTTPURLResponse(
46	                  url: url,
47	                  statusCode: stub.statusCode,
48	                  httpVersion: "HTTP/1.1",
49	                  headerFields: ["Content-Type": "application/json"]
50	              )
51	        else {
52	            client?.urlProtocol(self, didFailWithError: URLError(.unsupportedURL))
53	            return
54	        }
55	        client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
56	        client?.urlProtocol(self, didLoad: stub.body)
57	        client?.urlProtocolDidFinishLoading(self)
58	    }
