import Foundation

/// Serves canned HTTP responses to a `URLSession` injected into `RobotConnection`,
/// which is the only way to exercise daemon status codes without a daemon.
///
/// Stubs bind to the session that carries them, not to a global table: `swift test
/// --parallel` runs separate suites concurrently, so a shared table lets one suite
/// answer another suite's requests, or wipe them mid-flight. `.serialized` is no
/// defence — it orders tests within one suite and says nothing about the others.
final class StubURLProtocol: URLProtocol {
    struct Stub: Sendable {
        let statusCode: Int
        let body: Data

        init(statusCode: Int, json: String = "{}") {
            self.statusCode = statusCode
            body = Data(json.utf8)
        }
    }

    /// Routes are keyed by path, optionally narrowed by a query:
    /// `/update/available` answers whatever the query is, while
    /// `/update/available?pre_release=true` answers only that one. The narrower key
    /// wins, so a table can pin one variant and let the bare path cover the rest —
    /// without it, `pre_release=true` and `false` collapse onto a single stub.
    static func makeSession(_ stubs: [String: Stub]) -> URLSession {
        let token = UUID().uuidString
        lock.withLock { sessions[token] = stubs }

        let configuration = URLSessionConfiguration.ephemeral
        configuration.protocolClasses = [StubURLProtocol.self]
        configuration.httpAdditionalHeaders = [tokenHeader: token]
        return URLSession(configuration: configuration)
    }

    private static let tokenHeader = "X-Stub-Session"
    private nonisolated(unsafe) static var sessions: [String: [String: Stub]] = [:]
    private static let lock = NSLock()

    private static func stub(for request: URLRequest) -> Stub? {
        guard let token = request.value(forHTTPHeaderField: tokenHeader),
              let url = request.url,
              let table = lock.withLock({ sessions[token] })
        else { return nil }

        if let query = url.query(), let narrow = table["\(url.path)?\(query)"] {
            return narrow
        }
        return table[url.path]
    }

    override static func canInit(with _: URLRequest) -> Bool {
        true
    }

    override static func canonicalRequest(for request: URLRequest) -> URLRequest {
        request
    }

    override func startLoading() {
        guard let url = request.url,
              let stub = Self.stub(for: request),
              let response = HTTPURLResponse(
                  url: url,
                  statusCode: stub.statusCode,
                  httpVersion: "HTTP/1.1",
                  headerFields: ["Content-Type": "application/json"]
              )
        else {
            client?.urlProtocol(self, didFailWithError: URLError(.unsupportedURL))
            return
        }
        client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
        client?.urlProtocol(self, didLoad: stub.body)
        client?.urlProtocolDidFinishLoading(self)
    }

    override func stopLoading() {}
}

import Foundation
@testable import ReachyKit
import Testing

/// `.ok` on a generated call turns every non-200 into an opaque `undocumented`
/// runtime error. These pin the explicit mappings that make the readiness gate
/// and the error banner say something actionable.
@Suite("RobotConnection status mapping")
struct RobotConnectionStatusMappingTests {
    private func makeConnection(_ stubs: [String: StubURLProtocol.Stub]) throws -> RobotConnection {
        try RobotConnection(address: RobotAddress(host: "10.0.0.9"), session: StubURLProtocol.makeSession(stubs))
    }

    @Test("503 on the readiness probe is the backend-not-running signal")
    func readinessProbeMaps503() async throws {
        let connection = try makeConnection([
            "/api/state/full": .init(statusCode: 503, json: #"{"detail": "Backend not running"}"#),
        ])

        await #expect(throws: ReachyKitError.backendNotRunning) {
            try await connection.probeBackendReady()
        }
    }

    @Test("an unexpected daemon status code keeps its number")
    func daemonStatusMaps500() async throws {
        let connection = try makeConnection(["/api/daemon/status": .init(statusCode: 500)])

        await #expect(throws: ReachyKitError.daemonRejected(statusCode: 500)) {
            _ = try await connection.daemonStatus()
        }
    }
}

import Foundation
@testable import ReachyKit
import Testing

/// The hardware id is a join key, not a display string: the robot hands out the same
/// value over BLE and advertises it as the mDNS `unit_id`, so recognising a
/// just-provisioned robot on the LAN is a plain `==`. Any reshaping breaks that
/// silently — nothing throws, the match simply never happens.
@Suite("RobotConnection handshake identity")
struct RobotConnectionHandshakeTests {
    private static func status(hardwareID: String?) -> String {
        let field = hardwareID.map { "\"\($0)\"" } ?? "null"
        return """
        {"type": "daemon_status", "robot_name": "reachy_mini", "state": "running",
         "wireless_version": true, "desktop_app_daemon": false,
         "backend_status": null, "version": "1.9.0", "hardware_id": \(field)}
        """
    }

    private func makeConnection(_ stubs: [String: StubURLProtocol.Stub]) throws -> RobotConnection {
        try RobotConnection(address: RobotAddress(host: "10.0.0.9"), session: StubURLProtocol.makeSession(stubs))
    }

    @Test("the hardware id the status reports is carried through verbatim")
    func usesHardwareIDFromStatus() async throws {
        let connection = try makeConnection([
            "/api/daemon/status": .init(statusCode: 200, json: Self.status(hardwareID: "9f86d081884c7d65")),
            "/api/daemon/robot-name": .init(statusCode: 200, json: #"{"name": "testbot"}"#),
        ])

        let handshake = try await connection.handshake()

        #expect(handshake.identity.hardwareID == "9f86d081884c7d65")
    }

    @Test("a daemon that omits the field falls back to the dedicated route, unwrapping its one key")
    func fallsBackToHardwareIDRoute() async throws {
        let connection = try makeConnection([
            "/api/daemon/status": .init(statusCode: 200, json: Self.status(hardwareID: nil)),
            "/api/daemon/hardware-id": .init(statusCode: 200, json: #"{"hardware_id": "9f86d081884c7d65"}"#),
            "/api/daemon/robot-name": .init(statusCode: 200, json: #"{"name": "testbot"}"#),
        ])

        let handshake = try await connection.handshake()

        #expect(handshake.identity.hardwareID == "9f86d081884c7d65")
    }

    @Test("a daemon with no robot attached hands back no id rather than failing the handshake")
    func toleratesMissingHardwareID() async throws {
        let connection = try makeConnection([
            "/api/daemon/status": .init(statusCode: 200, json: Self.status(hardwareID: nil)),
            "/api/daemon/hardware-id": .init(statusCode: 200, json: #"{"hardware_id": null}"#),
            "/api/daemon/robot-name": .init(statusCode: 200, json: #"{"name": "reachy_mini"}"#),
        ])

        let handshake = try await connection.handshake()

        #expect(handshake.identity.hardwareID == nil)
        #expect(handshake.identity.deduplicationKey == "reachy_mini")
    }

    @Test("a stub keyed with a query wins over the bare path")
    func narrowerQueryKeyWins() async throws {
        let session = StubURLProtocol.makeSession([
            "/api/daemon/status": .init(statusCode: 500),
            "/api/daemon/status?verbose=1": .init(statusCode: 200, json: Self.status(hardwareID: "abc")),
        ])
        let (data, response) = try await session.data(
            from: URL(string: "http://10.0.0.9:8000/api/daemon/status?verbose=1")!
        )

        #expect((response as? HTTPURLResponse)?.statusCode == 200)
        #expect(String(decoding: data, as: UTF8.self).contains("abc"))
    }
}

