24	/// Compatibility policy for the daemon API snapshot and hand-written WebSockets.
25	public enum DaemonCompatibilityPolicy {
26	    public static let minimumVersion = "1.9.0"
27	    public static let testedVersion = "1.9.0"
28	
29	    public static func evaluate(_ reported: String?) -> DaemonCompatibility {
30	        guard let reported, let current = SemanticVersion(reported),
31	              let minimum = SemanticVersion(minimumVersion),
32	              let tested = SemanticVersion(testedVersion)
33	        else { return .unknown(reported: reported) }
34	
35	        guard current.major == tested.major, current >= minimum else {
36	            return .unsupported(reported: reported, minimum: minimumVersion)
37	        }
38	        return current > tested
39	            ? .untestedNewer(reported: reported, tested: testedVersion)
40	            : .supported
41	    }
42	}
