44	private struct SemanticVersion: Comparable, Sendable {
45	    let major: Int
46	    let minor: Int
47	    let patch: Int
48	
49	    init?(_ rawValue: String) {
50	        let normalized = rawValue.hasPrefix("v") ? String(rawValue.dropFirst()) : rawValue
51	        guard let core = normalized.split(separator: "-", maxSplits: 1).first else { return nil }
52	        let components = core.split(separator: ".")
53	        guard components.count >= 3,
54	              let major = Int(components[0]),
55	              let minor = Int(components[1]),
56	              let patch = Int(components[2])
57	        else { return nil }
58	        self.major = major
59	        self.minor = minor
60	        self.patch = patch
61	    }
62	
63	    static func < (lhs: Self, rhs: Self) -> Bool {
64	        (lhs.major, lhs.minor, lhs.patch) < (rhs.major, rhs.minor, rhs.patch)
65	    }
66	}
