3	/// Both transitions are multi-step protocols against the daemon, not single
4	/// calls: `/move/play/wake_up` and `/move/play/goto_sleep` only play animations
5	/// and never touch the motor control mode, and they answer 503 while the robot
6	/// backend is down. Enabling and cutting motor power is the caller's job.
7	public extension RobotSession {
8	    /// The branch is picked from a freshly fetched status rather than `lastStatus`,
9	    /// which may be a poll interval out of date — long enough to send motor
10	    /// commands at a backend that is already gone.
11	    func wake() async {
12	        guard let client, powerTransition == nil else { return }
13	        lastError = nil
14	        // Claimed before the first suspension point: `@MainActor` re-enters on
15	        // every `await`, so a later latch would let a double tap through.
16	        powerTransition = .wakingUp
17	        defer { powerTransition = nil }
18	        do {
19	            let status = try await client.daemonStatus()
20	            lastStatus = status
21	            guard status.state == .running else {
22	                // `wake_up=true` has the daemon enable the motors and play the
23	                // animation itself once the backend is up.
24	                _ = await runBackendStart(wakeUp: true, client: client)
25	                return
26	            }
27	            try await client.setMotorMode(.enabled)
28	            try await Task.sleep(for: configuration.motorSettleDelay)
29	            let uuid = try await client.wakeUp()
30	            await waitForMoveToFinish(uuid, client: client)
31	        } catch {
32	            lastError = Self.describe(error)
33	        }
34	    }
35	
36	    /// Mirror image of wake: the animation must finish *before* power is cut,
37	    /// otherwise the head drops wherever it happens to be.
38	    func sleep() async {
39	        guard let client, powerTransition == nil else { return }
40	        lastError = nil
41	        powerTransition = .goingToSleep
42	        defer { powerTransition = nil }
43	        do {
44	            let uuid = try await client.gotoSleep()
45	            await waitForMoveToFinish(uuid, client: client)
46	            try await client.setMotorMode(.disabled)
47	        } catch {
48	            lastError = Self.describe(error)
49	        }
50	    }
51	}
