import Foundation

/// Projects the connection phase onto the stepper's rows.
///
/// Kept here rather than in the view so the mapping is testable as a plain
/// table, and so progress is monotonic by construction: the outcome is derived
/// from the phase every time instead of being accumulated, which is what forces
/// upstream to carry a high-water mark.
public extension RobotSession.ConnectionPhase {
    func outcome(for stage: RobotSession.ConnectionStage) -> RobotSession.StageOutcome {
        switch self {
        case .idle: .pending
        case .connected, .unreachable: .done
        case let .connecting(step): step.outcome(for: stage)
        }
    }
}

private extension RobotSession.ConnectionStep {
    /// Which stage the attempt is standing on, and how that one row reads. Every
    /// earlier stage is finished by definition — the attempt could not have got
    /// here otherwise — and every later one has not been tried.
    var position: (stage: RobotSession.ConnectionStage, outcome: RobotSession.StageOutcome) {
        switch self {
        case .handshaking: (.connect, .active)
        case .checkingBackend: (.backend, .active)
        case .needsDaemonUpdate: (.compatibility, .attention)
        case .backendUnavailable: (.backend, .attention)
        case let .failed(stage, _): (stage, .failed)
        }
    }

    func outcome(for stage: RobotSession.ConnectionStage) -> RobotSession.StageOutcome {
        let current = position
        guard stage != current.stage else { return current.outcome }
        return stage.rawValue < current.stage.rawValue ? .done : .pending
    }
}

import Foundation

/// The daemon's self-update surface, reached through the session so the UI never
/// builds a URL of its own.
///
/// Deliberately not guarded by `assertSupportedDaemon()`: updating is precisely what
/// an unsupported daemon is for. ADR 0001 bars the *command* surface, and version
/// negotiation is not part of it.
public extension RobotSession {
    /// False on a Lite robot, which never mounts `/update/*`.
    var canUpdateDaemon: Bool {
        client is any DaemonUpdateClient && supportsWirelessFeatures
    }

    func availableUpdate(preRelease: Bool) async throws -> DaemonUpdateAvailability {
        try await withUpdateClient { try await $0.availableUpdate(preRelease: preRelease) }
    }

    /// Returns the job id whose log `updateLog(jobID:)` streams.
    func startUpdate(preRelease: Bool) async throws -> String {
        try await withUpdateClient { try await $0.startUpdate(preRelease: preRelease) }
    }

    func updateLog(jobID: String) throws -> AsyncStream<UpdateLogEvent> {
        guard let address else { throw ReachyKitError.notConnected }
        return try UpdateLogStreamClient(address: address, jobID: jobID).events()
    }

    /// Waits out the `systemctl restart` an update ends with and reports the version
    /// the daemon came back on.
    ///
    /// This is the only honest completion signal: the restart kills the process — and
    /// the in-memory job register with it — before the terminal `done` frame is ever
    /// written, so neither the socket nor `/update/info` can confirm success. `nil`
    /// means the daemon never answered again.
    func reconnectAfterUpdate(
        timeout: Duration = .seconds(120),
        pollInterval: Duration = .seconds(3)
    ) async -> String? {
        guard let address else { return nil }
        let deadline = ContinuousClock.now + timeout
        while ContinuousClock.now < deadline, !Task.isCancelled {
            try? await Task.sleep(for: pollInterval)
            if await connect(to: address), let version = lastStatus?.version {
                return version
            }
            // A halted attempt still read the status, so an update that landed but
            // stayed below the baseline reports its real version rather than nothing.
            if case .connecting(.needsDaemonUpdate) = phase, let version = lastStatus?.version {
                return version
            }
        }
        return nil
    }
}

extension RobotSession {
    func withUpdateClient<T>(_ call: (any DaemonUpdateClient) async throws -> T) async throws -> T {
        guard let client else { throw ReachyKitError.notConnected }
        guard let updateClient = client as? any DaemonUpdateClient else {
            throw ReachyKitError.wirelessFeaturesUnavailable
        }
        do {
            let result = try await call(updateClient)
            lastError = nil
            return result
        } catch {
            lastError = Self.describe(error)
            throw error
        }
    }
}

import Foundation
import Observation
import ReachyKit

/// Drives one robot software update: check, start, stream the log, wait out the
/// restart, confirm the new version.
@MainActor
@Observable
final class SystemUpdateModel {
    enum State: Equatable {
        case idle
        case checking
        case upToDate(current: String)
        /// The robot itself has no route to PyPI. Nothing the app can fix.
        case robotOffline(current: String)
        case available(current: String, latest: String)
        case installing
        /// The log socket closed, which is what the daemon restarting looks like.
        case restarting
        case finished(version: String)
        case failed(String)
    }

    private(set) var state: State = .idle
    /// Shared with `LogConsoleView`, so pip output gets the same filter, pause and
    /// export the daemon journal has.
    let log = LogConsoleModel()

    private let session: RobotSession
    /// Injected only by tests — the WebSocket needs a live daemon otherwise.
    private let makeEvents: (String) throws -> AsyncStream<UpdateLogEvent>

    init(session: RobotSession, events: ((String) throws -> AsyncStream<UpdateLogEvent>)? = nil) {
        self.session = session
        makeEvents = events ?? { [session] jobID in try session.updateLog(jobID: jobID) }
    }

    var isBusy: Bool {
        switch state {
        case .checking, .installing, .restarting: true
        default: false
        }
    }

    func check(preRelease: Bool) async {
        state = .checking
        do {
            state = switch try await session.availableUpdate(preRelease: preRelease) {
            case let .upToDate(current): .upToDate(current: current)
            case let .robotOffline(current): .robotOffline(current: current)
            case let .available(current, latest): .available(current: current, latest: latest)
            }
        } catch {
            state = .failed(describe(error))
        }
    }

    /// Runs to a terminal state. The daemon dies mid-stream by design, so the socket
    /// closing is treated as "installed, now rebooting" rather than as a failure.
    func install(preRelease: Bool) async {
        guard case let .available(current, _) = state else { return }
        state = .installing
        log.clear()

        let jobID: String
        do {
            jobID = try await session.startUpdate(preRelease: preRelease)
        } catch {
            state = .failed(describe(error))
            return
        }

        do {
            for await event in try makeEvents(jobID) {
                switch event {
                case let .line(line):
                    log.ingest(line)
                case let .status(status):
                    if status == .failed {
                        state = .failed("The robot reported that the update failed.")
                        return
                    }
                case let .rejected(reason):
                    state = .failed(reason)
                    return
                case .closed:
                    break
                }
            }
        } catch {
            state = .failed(describe(error))
            return
        }

        state = .restarting
        await confirmRestart(from: current)
    }

    private func confirmRestart(from previous: String) async {
        guard let version = await session.reconnectAfterUpdate() else {
            state = .failed("The robot did not come back after the update. Power-cycle it and try again.")
            return
        }
        guard version != previous else {
            state = .failed(
                "The update finished but the robot still reports \(version). "
                    + "A new enough release may not be published yet."
            )
            return
        }
        state = .finished(version: version)
    }

    private func describe(_ error: Error) -> String {
        (error as? LocalizedError)?.errorDescription ?? error.localizedDescription
    }
}

import ReachyKit
import SwiftUI

/// Shown when the handshake found a robot whose daemon is below the supported
/// baseline. Retrying was never going to help, so this offers the one thing that
/// can: the daemon's own update route.
struct DaemonUpdateScreen: View {
    let session: RobotSession
    let requirement: DaemonUpdateRequirement

    @State private var model: SystemUpdateModel?
    @AppStorage("update.preRelease") private var preRelease = false
    @State private var showsLog = false

    private var state: SystemUpdateModel.State {
        model?.state ?? .idle
    }

    var body: some View {
        Form {
            Section {
                Label("This robot needs a software update", systemImage: "arrow.down.circle")
                    .font(.headline)
                LabeledContent("Robot runs", value: requirement.reported)
                LabeledContent("This app needs", value: requirement.minimum)
            } footer: {
                Text(
                    requirement.canSelfUpdate
                        ? "The robot downloads the update itself, so it needs internet access. "
                            + "It restarts when the update finishes."
                        : "This robot cannot update itself over the network. "
                            + "Connect it to the official desktop app over USB to update it."
                )
            }

            if requirement.canSelfUpdate {
                Section("Update") {
                    statusRow
                    actions
                }
            }

            Section {
                Button("Disconnect", role: .destructive) { session.disconnect() }
            }
        }
        .formStyle(.grouped)
        .navigationTitle("Robot update")
        .task {
            guard model == nil else { return }
            let model = SystemUpdateModel(session: session)
            self.model = model
            if requirement.canSelfUpdate {
                await model.check(preRelease: preRelease)
            }
        }
        .sheet(isPresented: $showsLog) {
            if let model {
                NavigationStack {
                    LogConsoleView(
                        model: model.log,
                        source: session.address?.displayString ?? "robot",
                        emptyDescription: "The robot has not sent any installer output yet."
                    )
                    .navigationTitle("Update log")
                    .toolbar {
                        ToolbarItem(placement: .cancellationAction) {
                            Button("Done") { showsLog = false }
                        }
                    }
                }
            }
        }
    }

    @ViewBuilder
    private var statusRow: some View {
        switch state {
        case .idle, .checking:
            Label("Checking for updates…", systemImage: "arrow.triangle.2.circlepath")
        case let .upToDate(current):
            // Reachable when the robot is genuinely on the newest published release
            // yet still older than this app expects.
            Label(
                "The robot is on \(current), the newest release available to it.",
                systemImage: "exclamationmark.triangle"
            )
            .foregroundStyle(.orange)
        case let .robotOffline(current):
            Label(
                "The robot (\(current)) can't reach the internet, so it can't download an update.",
                systemImage: "wifi.exclamationmark"
            )
            .foregroundStyle(.orange)
        case let .available(current, latest):
            LabeledContent("Available") { Text("\(current) → \(latest)").monospaced() }
        case .installing:
            Label("Installing — this takes a minute or two…", systemImage: "arrow.down.circle")
        case .restarting:
            Label("The robot is restarting…", systemImage: "arrow.clockwise")
        case let .finished(version):
            Label("Updated to \(version).", systemImage: "checkmark.circle")
                .foregroundStyle(.green)
        case let .failed(message):
            Label(message, systemImage: "xmark.octagon")
                .foregroundStyle(.red)
        }
    }

    @ViewBuilder
    private var actions: some View {
        Toggle("Include pre-release versions", isOn: $preRelease)
            .disabled(model?.isBusy ?? true)
            .onChange(of: preRelease) { _, newValue in
                Task { await model?.check(preRelease: newValue) }
            }

        if case .available = state {
            Button("Update now") {
                Task { await model?.install(preRelease: preRelease) }
            }
        } else if case .finished = state {
            if let address = session.address {
                Button("Connect now") {
                    Task { await session.connect(to: address) }
                }
            }
        } else if !(model?.isBusy ?? true) {
            Button("Check again") {
                Task { await model?.check(preRelease: preRelease) }
            }
        }

        if model?.log.entries.isEmpty == false {
            Button("Show installer log") { showsLog = true }
        }
    }
}

