/// `GET /wifi/prov_key`.
public struct WiFiProvisioningKey: Equatable, Sendable, Decodable {
    /// Key id. The robot rotates its keypair every 600 s and rejects a stale one.
    public let kid: String
    /// Base64 of the raw 32-byte X25519 public key.
    public let pk: String
    public let alg: String

    public init(kid: String, pk: String, alg: String = WiFiPasswordSeal.algorithm) {
        self.kid = kid
        self.pk = pk
        self.alg = alg
    }
}

/// The `WIFI_CONNECT_ENC` / `POST /wifi/connect_sealed` payload.
public struct SealedWiFiCredentials: Equatable, Sendable, Encodable {
    public let ssid: String
    public let kid: String
    /// Base64 of this client's raw 32-byte ephemeral X25519 public key.
    public let epk: String
    /// Base64 of the 12-byte AES-GCM nonce.
    public let nonce: String
    /// Base64 of `ciphertext ‖ 16-byte tag`. CryptoKit keeps them apart; Python's
    /// `AESGCM.decrypt` expects them joined.
    public let ct: String

