import Foundation

/// The robot's ephemeral key for sealing a Wi-Fi password, from `WIFI_KEYEX` over BLE
/// or `GET /wifi/prov_key` over HTTP.
public struct WiFiProvisioningKey: Equatable, Sendable, Decodable {
    /// The robot rotates its keypair roughly every 10 minutes and refuses a stale id,
    /// which it reports as bad credentials — so that error deserves one retry with a
    /// fresh key before the PIN is blamed.
    public let kid: String
    /// Base64 of the raw 32-byte X25519 public key.
    public let pk: String
    public let alg: String

    public static let supportedAlgorithm = "x25519-hkdf-sha256-aesgcm"

    public init(kid: String, pk: String, alg: String = WiFiProvisioningKey.supportedAlgorithm) {
        self.kid = kid
        self.pk = pk
        self.alg = alg
    }
}

/// The `WIFI_CONNECT_ENC` / `POST /wifi/connect_sealed` payload. Field names are fixed
/// by the daemon's Pydantic model, so the JSON is emitted with no key strategy.
public struct SealedWiFiCredentials: Equatable, Sendable, Encodable {
    public let ssid: String
    public let kid: String
    /// Base64 of this client's raw 32-byte ephemeral X25519 public key.
    public let epk: String
    /// Base64 of the 12-byte AES-GCM nonce.
    public let nonce: String
    /// Base64 of `ciphertext ‖ 16-byte tag`. CryptoKit exposes the two separately;
    /// Python's `AESGCM.decrypt` expects them joined.
    public let ct: String

    public func jsonString() throws -> String {
        let data = try JSONEncoder().encode(self)
        guard let json = String(bytes: data, encoding: .utf8) else {
            throw ReachyKitError.daemonRejected(statusCode: -1)
        }
        return json
    }
}

import Foundation

/// One robot seen while scanning.
///
/// `id` is CoreBluetooth's per-host identifier, not the Bluetooth address, so it is
/// meaningful only on this device. Every robot advertises the same local name, so two
/// in range are told apart by signal strength until one is connected and its
/// `hardwareID` can be read.
public struct BLEPeripheralSnapshot: Identifiable, Hashable, Sendable {
    public let id: UUID
    public let name: String
    public let rssi: Int

    public init(id: UUID, name: String, rssi: Int) {
        self.id = id
        self.name = name
        self.rssi = rssi
    }
}

/// The CoreBluetooth surface this client needs, kept behind a protocol so the command
/// protocol above it is testable without hardware — the robot's BLE service is
/// Linux/BlueZ, so no simulator can ever stand in for it.
///
/// Only `String`, `Data` and `UUID` cross this boundary: `CBPeripheral` and
/// `CBCharacteristic` are not `Sendable` and never leave the adapter.
public protocol BLETransport: Sendable, AnyObject {
    var availability: BLEAvailability { get }
    /// Peripherals seen so far, newest reading per robot.
    var discovered: [BLEPeripheralSnapshot] { get }
    /// Largest payload one write can carry. `WIFI_CONNECT_ENC` is around 260 bytes
    /// against a default ATT MTU of 185, so this decides whether BLE provisioning
    /// works at all on a given phone.
    var maximumWriteLength: Int { get }

    func startScan() throws
    func stopScan()
    func connect(_ id: UUID) async throws
    func disconnect()

    func write(_ payload: Data, to characteristic: BLECharacteristicID) async throws
    func read(_ characteristic: BLECharacteristicID) async throws -> Data
    func setNotify(_ enabled: Bool, for characteristic: BLECharacteristicID) async throws
    /// Values pushed on the response characteristic. Only proxied commands notify.
    func notifications() -> AsyncStream<Data>
}

public enum BLETransportError: Error, Equatable, Sendable {
    case unavailable(BLEAvailability)
    case notConnected
    case characteristicMissing(BLECharacteristicID)
    case connectionFailed(String)
    /// The payload exceeds what one ATT write can carry. The robot's command handler
    /// ignores write offsets, so a fragmented write would be dispatched as two
    /// separate commands rather than reassembled.
    case payloadTooLong(bytes: Int, limit: Int)
    case timedOut
}

extension BLETransportError: LocalizedError {
    public var errorDescription: String? {
        switch self {
        case let .unavailable(availability):
            switch availability {
            case .unsupported: "This device has no Bluetooth."
            case .unauthorized: "Bluetooth access is turned off for this app."
            case .poweredOff: "Bluetooth is switched off."
            case .unknown, .ready: "Bluetooth is not ready."
            }
        case .notConnected: "Not connected to a robot over Bluetooth."
        case let .characteristicMissing(characteristic):
            "The robot did not offer the \(characteristic) characteristic."
        case let .connectionFailed(message): message
        case let .payloadTooLong(bytes, limit):
            "The robot accepts \(limit) bytes per message and this one is \(bytes)."
        case .timedOut: "The robot did not answer in time."
        }
    }
}

import Foundation

/// Sends one command at a time and returns its real reply.
///
/// **The reply arrives two different ways and upstream's own documentation gets this
/// wrong.** `CommandCharacteristic.WriteValue` assigns the response characteristic's
/// value directly, without notifying, so synchronous commands — `PING`, `STATUS`,
/// `PIN_…`, `JOURNAL_*` — answer on a *read* and never notify. Only commands proxied
/// to the daemon go through `_emit_response`, and those answer `OK: working`
/// immediately and deliver the real result as a notification later.
///
/// So the sequence is: write, read, and only await a notification if the read was the
/// ack. Awaiting a notification unconditionally hangs forever on a `PING`.
///
/// Write-with-response is what makes the read safe: BlueZ acknowledges the ATT write
/// only after its handler returns, by which point the value is already set.
public actor BLECommandPump {
    private let transport: any BLETransport
    /// Actors are reentrant, so serialisation has to be built rather than assumed:
    /// the single response characteristic carries no correlation id, and two commands
    /// in flight would race for the same reply.
    private var tail: Task<Void, Never>?

    public init(transport: any BLETransport) {
        self.transport = transport
    }

    /// Subscribes to the response characteristic. Must run before any proxied command,
    /// and again after every reconnect — the robot resets its state on disconnect.
    public func prepare() async throws {
        try await transport.setNotify(true, for: .response)
    }

    public func send(_ command: BLECommand) async throws -> BLEReply {
        try await serialized { [transport] in
            let payload = command.data
            let limit = transport.maximumWriteLength
            guard payload.count <= limit else {
                throw BLETransportError.payloadTooLong(bytes: payload.count, limit: limit)
            }

            guard command.repliesToWrite else {
                // `CMD_*` crashes the robot's reply encoder on success, so the write
                // itself reporting an error says nothing about whether it ran.
                try? await transport.write(payload, to: .command)
                return .ok("dispatched")
            }

            // Started before the write so a fast notification cannot land in the gap.
            let notifications = transport.notifications()
            try await transport.write(payload, to: .command)

            let immediate = BLEResponseParser.parse(try await transport.read(.response))
            guard immediate.isWorkingAck else {
                return immediate
            }
            return try await awaitResult(on: notifications, timeout: command.timeout)
        }
    }

    /// The robot sets the response value *before* checking whether anyone subscribed,
    /// so a notification lost to a resubscribe or a dropped packet is still recoverable
    /// by reading the characteristic once the wait expires.
    private func awaitResult(on notifications: AsyncStream<Data>, timeout: Duration) async throws -> BLEReply {
        let notified = Task { () -> BLEReply? in
            for await data in notifications {
                let reply = BLEResponseParser.parse(data)
                if !reply.isWorkingAck {
                    return reply
                }
            }
            return nil
        }
        let expiry = Task {
            try? await Task.sleep(for: timeout)
            notified.cancel()
        }
        defer { expiry.cancel() }

        if let reply = await notified.value {
            return reply
        }
        let recovered = BLEResponseParser.parse(try await transport.read(.response))
        guard !recovered.isWorkingAck else {
            throw BLETransportError.timedOut
        }
        return recovered
    }

    private func serialized<T: Sendable>(_ work: @escaping @Sendable () async throws -> T) async throws -> T {
        let previous = tail
        let task = Task { () -> T in
            await previous?.value
            return try await work()
        }
        tail = Task { _ = try? await task.value }
        return try await task.value
    }
}

import Foundation
@testable import ReachyKit

/// Stands in for the robot's GATT service, which is Linux/BlueZ and therefore
/// impossible to simulate — only real hardware speaks it.
///
/// Scripted per command: `readReplies` is what a read of the response characteristic
/// returns, `notifications` what arrives afterwards. A command with no scripted
/// notification models a synchronous reply.
final class FakeBLETransport: BLETransport, @unchecked Sendable {
    struct Script {
        /// What the response characteristic reads back straight after the write.
        var read: String
        /// Delivered as a notification afterwards. Nil for synchronous commands.
        var notify: String?
        /// Skips the notification entirely, so the pump has to fall back to a re-read.
        var dropsNotification = false
    }

    private let lock = NSLock()
    private var scripts: [String: Script] = [:]
    private var writes: [String] = []
    private var overlappingWrites = false
    private var writeInFlight = false
    private var lastRead: String = ""
    private var continuation: AsyncStream<Data>.Continuation?

    var availability: BLEAvailability = .ready
    var discovered: [BLEPeripheralSnapshot] = []
    var maximumWriteLength = 512
    var writeError: (any Error)?
    /// Delay inserted inside `write`, so an overlap between two `send` calls is
    /// observable rather than theoretical.
    var writeDelay: Duration = .zero

    init(scripts: [String: Script] = [:]) {
        self.scripts = scripts
    }

    var writtenCommands: [String] {
        lock.withLock { writes }
    }

    var sawOverlappingWrites: Bool {
        lock.withLock { overlappingWrites }
    }

    func script(_ command: String, read: String, notify: String? = nil, dropsNotification: Bool = false) {
        lock.withLock {
            scripts[command] = Script(read: read, notify: notify, dropsNotification: dropsNotification)
        }
    }

    func startScan() throws {}
    func stopScan() {}
    func connect(_: UUID) async throws {}
    func disconnect() {}
    func setNotify(_: Bool, for _: BLECharacteristicID) async throws {}

    func notifications() -> AsyncStream<Data> {
        let (stream, continuation) = AsyncStream.makeStream(of: Data.self)
        lock.withLock { self.continuation = continuation }
        return stream
    }

    func write(_ payload: Data, to _: BLECharacteristicID) async throws {
        if let writeError {
            throw writeError
        }
        let command = String(decoding: payload, as: UTF8.self)
        lock.withLock {
            if writeInFlight {
                overlappingWrites = true
            }
            writeInFlight = true
            writes.append(command)
        }
        if writeDelay > .zero {
            try? await Task.sleep(for: writeDelay)
        }

        let script = lock.withLock { scripts[command] }
        lock.withLock {
            writeInFlight = false
            lastRead = script?.read ?? "ECHO: \(command)"
        }
        guard let script, let notify = script.notify, !script.dropsNotification else { return }
        // A real notification never lands before the write completes.
        Task { [weak self] in
            guard let self else { return }
            let continuation = lock.withLock { self.continuation }
            lock.withLock { self.lastRead = notify }
            continuation?.yield(Data(notify.utf8))
        }
    }

    func read(_: BLECharacteristicID) async throws -> Data {
        Data(lock.withLock { lastRead }.utf8)
    }
}

import Foundation
@testable import ReachyKit
import Testing

/// The robot answers on two different channels depending on the command, and upstream's
/// own documentation describes only one of them. Getting this wrong does not produce a
/// wrong answer — it produces a client that hangs forever on `PING`.
@Suite("BLECommandPump")
struct BLECommandPumpTests {
    @Test("a synchronous command answers on the read and never waits for a notification",
          .timeLimit(.minutes(1)))
    func doesNotAwaitNotificationsForSyncCommands() async throws {
        // No notification is scripted at all: the robot's `WriteValue` sets the read
        // value directly and never calls `send_notification` for these.
        let transport = FakeBLETransport()
        transport.script("PING", read: "PONG")
        let pump = BLECommandPump(transport: transport)

        #expect(try await pump.send(.ping) == .pong)
    }

    @Test("a proxied command skips its ack and returns the notification that follows",
          .timeLimit(.minutes(1)))
    func awaitsTheRealResultAfterTheAck() async throws {
        let transport = FakeBLETransport()
        transport.script("WIFI_SCAN", read: BLEReply.workingAck, notify: #"["Home","Cafe"]"#)
        let pump = BLECommandPump(transport: transport)

        #expect(try await pump.send(.wifiScan) == .payload(#"["Home","Cafe"]"#))
    }

    @Test("only a literal working ack is skipped — a real OK is the answer", .timeLimit(.minutes(1)))
    func treatsOtherOKRepliesAsResults() async throws {
        let transport = FakeBLETransport()
        transport.script("PIN_12345", read: "OK: Connected")
        let pump = BLECommandPump(transport: transport)

        #expect(try await pump.send(.authenticate(pin: "12345")) == .ok("Connected"))
    }

    @Test("a lost notification is recovered by re-reading, which the robot leaves valid",
          .timeLimit(.minutes(1)))
    func fallsBackToReadingWhenTheNotificationIsLost() async throws {
        let transport = FakeBLETransport()
        transport.script(
            "WIFI_KEYEX",
            read: BLEReply.workingAck,
            notify: #"{"kid":"abc","pk":"key","alg":"x25519-hkdf-sha256-aesgcm"}"#,
            dropsNotification: true
        )
        let pump = BLECommandPump(transport: transport)

        // The value the robot never managed to push is still readable.
        transport.script("WIFI_KEYEX", read: BLEReply.workingAck, notify: nil)
        let reply = try await pump.send(.wifiStatus)

        #expect(reply == .echo("WIFI_STATUS"))
    }

    @Test("commands are serialised — one response characteristic carries no correlation id",
          .timeLimit(.minutes(1)))
    func serialisesConcurrentSends() async throws {
        let transport = FakeBLETransport()
        transport.writeDelay = .milliseconds(30)
        transport.script("PING", read: "PONG")
        transport.script("STATUS", read: "OK: System running")
        let pump = BLECommandPump(transport: transport)

        async let first = pump.send(.ping)
        async let second = pump.send(.status)
        _ = try await (first, second)

        #expect(transport.sawOverlappingWrites == false)
        #expect(transport.writtenCommands.count == 2)
    }

