2	
3	/// Sends one command at a time and returns its real reply.
4	///
5	/// **The reply arrives two different ways and upstream's own documentation gets this
6	/// wrong.** `CommandCharacteristic.WriteValue` assigns the response characteristic's
7	/// value directly, without notifying, so synchronous commands — `PING`, `STATUS`,
8	/// `PIN_…`, `JOURNAL_*` — answer on a *read* and never notify. Only commands proxied
9	/// to the daemon go through `_emit_response`, and those answer `OK: working`
10	/// immediately and deliver the real result as a notification later.
11	///
12	/// So the sequence is: write, read, and only await a notification if the read was the
13	/// ack. Awaiting a notification unconditionally hangs forever on a `PING`.
14	///
15	/// Write-with-response is what makes the read safe: BlueZ acknowledges the ATT write
16	/// only after its handler returns, by which point the value is already set.
17	public actor BLECommandPump {
18	    private let transport: any BLETransport
19	    /// Actors are reentrant, so serialisation has to be built rather than assumed:
20	    /// the single response characteristic carries no correlation id, and two commands
21	    /// in flight would race for the same reply.
22	    private var tail: Task<Void, Never>?
23	
24	    public init(transport: any BLETransport) {
25	        self.transport = transport
26	    }
27	
28	    /// Subscribes to the response characteristic. Must run before any proxied command,
29	    /// and again after every reconnect — the robot resets its state on disconnect.
30	    public func prepare() async throws {
31	        try await transport.setNotify(true, for: .response)
32	    }
33	
34	    public func send(_ command: BLECommand) async throws -> BLEReply {
35	        try await serialized { [self, transport] in
36	            let payload = command.data
37	            let limit = transport.maximumWriteLength
38	            guard payload.count <= limit else {
39	                throw BLETransportError.payloadTooLong(bytes: payload.count, limit: limit)
40	            }
41	
42	            guard command.repliesToWrite else {
43	                // `CMD_*` crashes the robot's reply encoder on success, so the write
44	                // itself reporting an error says nothing about whether it ran.
45	                try? await transport.write(payload, to: .command)
46	                return .ok("dispatched")
47	            }
48	
49	            // Started before the write so a fast notification cannot land in the gap.
50	            let notifications = transport.notifications()
51	            try await transport.write(payload, to: .command)
52	
53	            let immediate = try await BLEResponseParser.parse(transport.read(.response))
54	            guard immediate.isWorkingAck else {
55	                return immediate
56	            }
57	            return try await awaitResult(on: notifications, timeout: command.timeout)
58	        }
59	    }
60	
61	    /// The robot sets the response value *before* checking whether anyone subscribed,
62	    /// so a notification lost to a resubscribe or a dropped packet is still recoverable
63	    /// by reading the characteristic once the wait expires.
64	    private func awaitResult(on notifications: AsyncStream<Data>, timeout: Duration) async throws -> BLEReply {
65	        let notified = Task { () -> BLEReply? in
66	            for await data in notifications {
67	                let reply = BLEResponseParser.parse(data)
68	                if !reply.isWorkingAck {
69	                    return reply
70	                }
71	            }
72	            return nil
73	        }
74	        let expiry = Task {
75	            try? await Task.sleep(for: timeout)
76	            notified.cancel()
77	        }
78	        defer { expiry.cancel() }
79	
80	        if let reply = await notified.value {
81	            return reply
82	        }
83	        let recovered = try await BLEResponseParser.parse(transport.read(.response))
84	        guard !recovered.isWorkingAck else {
85	            throw BLETransportError.timedOut
86	        }
87	        return recovered
88	    }
89	
90	    private func serialized<T: Sendable>(_ work: @escaping @Sendable () async throws -> T) async throws -> T {
91	        let previous = tail
92	        let task = Task { () -> T in
93	            await previous?.value
94	            return try await work()
95	        }
96	        tail = Task { _ = try? await task.value }
97	        return try await task.value
98	    }
99	}
