1	import Foundation
2	@testable import ReachyKit
3	
4	/// Stands in for the robot's GATT service, which is Linux/BlueZ and therefore
5	/// impossible to simulate — only real hardware speaks it.
6	///
7	/// Scripted per command: `readReplies` is what a read of the response characteristic
8	/// returns, `notifications` what arrives afterwards. A command with no scripted
9	/// notification models a synchronous reply.
10	final class FakeBLETransport: BLETransport, @unchecked Sendable {
11	    struct Script {
12	        /// What the response characteristic reads back straight after the write.
13	        var read: String
14	        /// Delivered as a notification afterwards. Nil for synchronous commands.
15	        var notify: String?
16	        /// Skips the notification entirely, so the pump has to fall back to a re-read.
17	        var dropsNotification = false
18	    }
19	
20	    private let lock = NSLock()
21	    private var scripts: [String: Script] = [:]
22	    private var writes: [String] = []
23	    private var overlappingWrites = false
24	    private var writeInFlight = false
25	    private var lastRead: String = ""
26	    private var continuation: AsyncStream<Data>.Continuation?
27	
28	    var availability: BLEAvailability = .ready
29	    var discovered: [BLEPeripheralSnapshot] = []
30	    var maximumWriteLength = 512
31	    var writeError: (any Error)?
32	    /// Delay inserted inside `write`, so an overlap between two `send` calls is
33	    /// observable rather than theoretical.
34	    var writeDelay: Duration = .zero
35	
36	    init(scripts: [String: Script] = [:]) {
37	        self.scripts = scripts
38	    }
39	
40	    var writtenCommands: [String] {
41	        lock.withLock { writes }
42	    }
43	
44	    var sawOverlappingWrites: Bool {
45	        lock.withLock { overlappingWrites }
46	    }
47	
48	    func script(_ command: String, read: String, notify: String? = nil, dropsNotification: Bool = false) {
49	        lock.withLock {
50	            scripts[command] = Script(read: read, notify: notify, dropsNotification: dropsNotification)
51	        }
52	    }
53	
54	    func startScan() throws {}
55	    func stopScan() {}
56	    func connect(_: UUID) async throws {}
57	    func disconnect() {}
58	    func setNotify(_: Bool, for _: BLECharacteristicID) async throws {}
59	
60	    func notifications() -> AsyncStream<Data> {
61	        let (stream, continuation) = AsyncStream.makeStream(of: Data.self)
62	        lock.withLock { self.continuation = continuation }
63	        return stream
64	    }
65	
66	    func write(_ payload: Data, to _: BLECharacteristicID) async throws {
67	        if let writeError {
68	            throw writeError
69	        }
70	        let command = String(bytes: payload, encoding: .utf8) ?? ""
71	        lock.withLock {
72	            if writeInFlight {
73	                overlappingWrites = true
74	            }
75	            writeInFlight = true
76	            writes.append(command)
77	        }
78	        if writeDelay > .zero {
79	            try? await Task.sleep(for: writeDelay)
80	        }
81	
82	        let script = lock.withLock { scripts[command] }
83	        lock.withLock {
84	            writeInFlight = false
85	            lastRead = script?.read ?? "ECHO: \(command)"
86	        }
87	        guard let script, let notify = script.notify, !script.dropsNotification else { return }
88	        // A real notification never lands before the write completes.
89	        Task { [weak self] in
90	            guard let self else { return }
91	            let continuation = lock.withLock { self.continuation }
92	            lock.withLock { self.lastRead = notify }
93	            continuation?.yield(Data(notify.utf8))
94	        }
95	    }
96	
97	    func read(_: BLECharacteristicID) async throws -> Data {
98	        Data(lock.withLock { lastRead }.utf8)
99	    }
100	}
