import Foundation

/// Provisioning over Bluetooth, which is the only channel that works before the robot
/// is on any network at all.
public struct BLEProvisioningTransport: WiFiProvisioningTransport {
    private let pump: BLECommandPump
    private let transport: any BLETransport

    public init(pump: BLECommandPump, transport: any BLETransport) {
        self.pump = pump
        self.transport = transport
    }

    public func provisioningKey() async throws -> WiFiProvisioningKey {
        let json = try await pump.send(.wifiKeyExchange).value()
        return try JSONDecoder().decode(WiFiProvisioningKey.self, from: Data(json.utf8))
    }

    public func scanNetworks() async throws -> [String] {
        let reply = try await pump.send(.wifiScan).value()
        return WiFiScanResult.networks(in: reply)
    }

    public func connectSealed(_ payload: SealedWiFiCredentials) async throws {
        _ = try await pump.send(.wifiConnectSealed(json: payload.jsonString())).value()
    }

    /// Read straight off the status characteristic rather than sent as `WIFI_STATUS`:
    /// it needs no PIN session, costs one ATT read instead of a proxied round trip that
    /// answers twice, and carries exactly the live address a two-second poll is after.
    public func wifiStatus() async throws -> WiFiNetworkStatus {
        let raw = try await transport.read(.networkStatus)
        guard let text = String(bytes: raw, encoding: .utf8),
              let status = WiFiNetworkStatus(parsing: text)
        else {
            throw BLECommandError.other("The robot reported a network status this app could not read.")
        }
        return status
    }
}

import CryptoKit
import Foundation
@testable import ReachyKit

/// A robot that answers the provisioning protocol, with the two things worth scripting:
/// how many times it refuses the sealed payload, and when it admits to being on the
/// network. Its keys are real X25519 keys, so the sealing runs for real.
final class FakeProvisioningTransport: WiFiProvisioningTransport, @unchecked Sendable {
    private let lock = NSLock()
    private var issued: [WiFiProvisioningKey] = []
    private var accepted: [SealedWiFiCredentials] = []
    private var refusals = 0
    private var statusReads = 0

    /// Refuses this many sealed payloads with bad credentials before accepting one.
    var refusesFirst = 0
    /// The raw `WIFI_SCAN` reply, truncation and all.
    var scanReply = "[]"
    /// Reports `CONNECTED` once this many status reads have happened.
    var connectsAfterReads = Int.max

    var issuedKeys: [WiFiProvisioningKey] { lock.withLock { issued } }
    var sealedPayloads: [SealedWiFiCredentials] { lock.withLock { accepted } }

    func provisioningKey() async throws -> WiFiProvisioningKey {
        lock.withLock {
            let key = WiFiProvisioningKey(
                kid: "key-\(issued.count)",
                pk: Curve25519.KeyAgreement.PrivateKey().publicKey.rawRepresentation.base64EncodedString()
            )
            issued.append(key)
            return key
        }
    }

    func scanNetworks() async throws -> [String] {
        WiFiScanResult.networks(in: scanReply)
    }

    func connectSealed(_ payload: SealedWiFiCredentials) async throws {
        try lock.withLock {
            guard refusals >= refusesFirst else {
                refusals += 1
                throw BLECommandError.badCredentials
            }
            accepted.append(payload)
        }
    }

    func wifiStatus() async throws -> WiFiNetworkStatus {
        let reads = lock.withLock { () -> Int in
            statusReads += 1
            return statusReads
        }
        let raw = reads >= connectsAfterReads
            ? "CONNECTED [wlan0] 192.168.1.42"
            : "HOTSPOT [wlan0] 10.42.0.1"
        guard let status = WiFiNetworkStatus(parsing: raw) else {
            throw BLECommandError.other("unparseable fixture")
        }
        return status
    }
}

import Foundation
@testable import ReachyKit
import Testing

@Suite("Wi-Fi scan replies")
struct WiFiScanResultTests {
    @Test("a whole reply reads as itself")
    func readsCompleteReplies() {
        #expect(WiFiScanResult.networks(in: #"["Home","Cafe Wi-Fi"]"#) == ["Home", "Cafe Wi-Fi"])
    }

    /// The robot caps the reply at 180 bytes without saying so, so this is what an
    /// ordinary scan in a busy building looks like — not a corrupted one.
    @Test("a reply cut mid-name keeps every name that finished")
    func salvagesTruncatedReplies() {
        #expect(WiFiScanResult.networks(in: #"["Home","Cafe Wi-Fi","Offi"#) == ["Home", "Cafe Wi-Fi"])
    }

    @Test("hidden networks and repeats are not offered")
    func dropsEmptyAndDuplicateNames() {
        #expect(WiFiScanResult.networks(in: #"["Home","","Home","Cafe"]"#) == ["Home", "Cafe"])
    }

    @Test("a reply with nothing usable in it is empty, not a failure")
    func toleratesGarbage() {
        #expect(WiFiScanResult.networks(in: "").isEmpty)
        #expect(WiFiScanResult.networks(in: "[").isEmpty)
    }
}

@Suite("Wi-Fi provisioning")
struct WiFiProvisioningTests {
    @Test("a robot that accepts the first payload is asked for one key", .timeLimit(.minutes(1)))
    func sealsUnderOneKeyWhenAccepted() async throws {
        let transport = FakeProvisioningTransport()

        try await WiFiProvisioning.join(ssid: "Home", password: "REDACTED", pin: "AB12C", using: transport)

        #expect(transport.issuedKeys.count == 1)
        #expect(transport.sealedPayloads.count == 1)
    }

    /// The robot rotates its keypair every 600 s and reports a stale `kid` with the very
    /// same error as a wrong PIN. Retrying once under a fresh key is what separates them.
    @Test("a refusal buys exactly one retry, under a new key", .timeLimit(.minutes(1)))
    func retriesOnceWithAFreshKey() async throws {
        let transport = FakeProvisioningTransport()
        transport.refusesFirst = 1

        try await WiFiProvisioning.join(ssid: "Home", password: "REDACTED", pin: "AB12C", using: transport)

        #expect(transport.issuedKeys.map(\.kid) == ["key-0", "key-1"])
        let accepted = try #require(transport.sealedPayloads.first)
        #expect(accepted.kid == "key-1")
    }

    @Test("a second refusal is the PIN, and is not retried again", .timeLimit(.minutes(1)))
    func stopsAfterTheRetry() async throws {
        let transport = FakeProvisioningTransport()
        transport.refusesFirst = 2

        await #expect(throws: BLECommandError.badCredentials) {
            try await WiFiProvisioning.join(ssid: "Home", password: "REDACTED", pin: "AB12C", using: transport)
        }
        #expect(transport.issuedKeys.count == 2)
        #expect(transport.sealedPayloads.isEmpty)
    }

    @Test("the join is reported once the robot says it is on the network", .timeLimit(.minutes(1)))
    func reportsAJoin() async throws {
        let transport = FakeProvisioningTransport()
        transport.connectsAfterReads = 3

        let outcome = try await WiFiProvisioning.awaitJoin(
            using: transport,
            timeout: .seconds(30),
            pollInterval: .milliseconds(1)
        )

        guard case let .joined(status) = outcome else {
            Issue.record("expected a join, got \(outcome)")
            return
        }
        #expect(status.address == "192.168.1.42")
    }

    /// A robot that failed to join goes back to its own access point, so the last status
    /// is what the screen needs to say what happened rather than implying a brick.
    @Test("giving up reports where the robot ended up", .timeLimit(.minutes(1)))
    func reportsWhereItGaveUp() async throws {
        let transport = FakeProvisioningTransport()

        let outcome = try await WiFiProvisioning.awaitJoin(
            using: transport,
            timeout: .zero,
            pollInterval: .milliseconds(1)
        )

        #expect(outcome == .gaveUp(last: WiFiNetworkStatus(parsing: "HOTSPOT [wlan0] 10.42.0.1")))
    }
}

