import Foundation

/// Where the robot is on the network, as far as the channel currently in use can tell.
///
/// The two channels report genuinely different things and neither is a subset of the
/// other: the Bluetooth characteristic carries the live IP address but no list of saved
/// networks, and `GET /wifi/status` carries the saved networks but no address at all.
/// Each fills what it knows rather than inventing the rest.
public struct WiFiStatus: Equatable, Sendable {
    public enum Mode: Equatable, Sendable {
        /// The robot is serving its own access point, which is both its out-of-box
        /// state and where it retreats after a failed join.
        case hotspot
        case connected
        case offline
        /// An `nmcli` operation is in flight. Transient by definition — reported over
        /// HTTP only, and a poll should keep waiting rather than conclude anything.
        case busy
    }

    public let mode: Mode
    /// Bluetooth only.
    public let address: String?
    /// HTTP only.
    public let knownNetworks: [String]
    /// HTTP only.
    public let connectedNetwork: String?

    public init(
        mode: Mode,
        address: String? = nil,
        knownNetworks: [String] = [],
        connectedNetwork: String? = nil
    ) {
        self.mode = mode
        self.address = address
        self.knownNetworks = knownNetworks
        self.connectedNetwork = connectedNetwork
    }
}

public extension WiFiNetworkStatus {
    /// `ERROR` folds into `offline`: both mean the robot is on no network, and the
    /// distinction survives on `WiFiNetworkStatus` itself for the recovery console.
    var status: WiFiStatus {
        let mode: WiFiStatus.Mode = switch self.mode {
        case .hotspot: .hotspot
        case .connected: .connected
        case .offline, .error: .offline
        }
        return WiFiStatus(mode: mode, address: address)
    }
}

