            // 404 here means the route was never mounted, not that a resource is
            // missing: only `/update/info` takes an identifier that could be absent.
            if http.statusCode == 404, path != "/update/info" {
                throw ReachyKitError.wirelessFeaturesUnavailable
            }
            throw ReachyKitError.fromStatusCode(http.statusCode)
        }
        return try JSONDecoder.reachyDaemon.decode(T.self, from: data)
