5	/// viewport placed according to how much room there is.
6	///
7	/// The tab bar lives here rather than in the app target because the Live tab and
8	/// the Robot tab share a `RobotSession` and a `ViewportModel`, and because
9	/// whether Live exists at all depends on the size class — which an `App` cannot
10	/// read. Diagnostics is injected so the app target keeps owning its own screen
11	/// without a second, nested tab bar.
12	public struct ReachyRootView<Diagnostics: View>: View {
13	    private enum TabID: Hashable {
14	        case robot
15	        case live
16	        case diagnostics
17	    }
18	
19	    @State private var session = RobotSession()
20	    @State private var viewport = ViewportModel()
21	    @State private var tab: TabID = .robot
22	    @State private var showsAudioSettings = false
23	    @Environment(\.scenePhase) private var scenePhase
24	
25	    #if os(macOS)
26	        /// `horizontalSizeClass` does not exist on macOS, where a window is always
27	        /// wide enough for the two-column layout.
28	        private var isCompact: Bool {
29	            false
30	        }
31	    #else
32	        @Environment(\.horizontalSizeClass) private var horizontalSizeClass
33	        private var isCompact: Bool {
34	            horizontalSizeClass == .compact
35	        }
36	    #endif
37	
38	    private let diagnostics: Diagnostics
39	
40	    public init(@ViewBuilder diagnostics: () -> Diagnostics) {
41	        self.diagnostics = diagnostics()
42	    }
43	
44	    public var body: some View {
45	        TabView(selection: $tab) {
46	            Tab("Robot", systemImage: "figure.wave", value: TabID.robot) {
47	                robotTab
48	            }
49	            if offersLiveTab {
50	                Tab("Live", systemImage: "cube.transparent", value: TabID.live) {
51	                    liveTab
52	                }
53	            }
54	            Tab("Diagnostics", systemImage: "stethoscope", value: TabID.diagnostics) {
55	                diagnostics
56	            }
57	        }
58	        .task(id: viewportAddress) {
59	            if let viewportAddress {
60	                viewport.attach(to: viewportAddress)
61	            } else {
62	                viewport.detach()
63	            }
64	        }
65	        .onChange(of: viewportIsOnScreen, initial: true) { _, onScreen in
66	            viewport.setActive(onScreen)
67	        }
68	        .onChange(of: offersLiveTab) { _, offered in
69	            // The tab it points at is about to stop existing; SwiftUI would pick
