2	
3	enum LogLevel: Int, CaseIterable, Sendable, Comparable, CustomStringConvertible {
4	    case debug, info, warning, error
5	
6	    static func < (lhs: Self, rhs: Self) -> Bool {
7	        lhs.rawValue < rhs.rawValue
8	    }
9	
10	    var description: String {
11	        switch self {
12	        case .debug: "debug"
13	        case .info: "info"
14	        case .warning: "warning"
15	        case .error: "error"
16	        }
17	    }
18	}
19	
20	/// One journal line. `text` stays identical to what the daemon sent — copy and
21	/// export ship the original, not a re-rendered version.
22	struct LogEntry: Identifiable, Sendable, Equatable {
23	    let id: Int
24	    let timestamp: String?
25	    let message: String
26	    let level: LogLevel
27	    let text: String
28	
29	    init(id: Int, raw: String) {
30	        self.id = id
31	        text = raw
32	        let parts = raw.split(separator: " ", maxSplits: 1, omittingEmptySubsequences: false)
33	        if parts.count == 2, let first = parts.first, Self.isTimestamp(first) {
34	            timestamp = String(first)
35	            message = String(parts[1])
36	        } else {
37	            timestamp = nil
38	            message = raw
39	        }
40	        level = Self.level(of: message)
41	    }
42	
43	    private static func isTimestamp(_ token: Substring) -> Bool {
44	        token.count >= 19 && token.dropFirst(10).first == "T" && token.prefix(4).allSatisfy(\.isNumber)
