    func startUpdate(preRelease _: Bool) async throws -> String {
        throw URLError(.unsupportedURL)
    }

    func updateInfo(jobID _: String) async throws -> DaemonUpdateJob {
        throw URLError(.unsupportedURL)
    }
}

