            }
        }
    }

    @ViewBuilder
    private var statusRow: some View {
        switch model?.state ?? .idle {
        case .idle:
            LabeledContent("Installed", value: session.lastStatus?.version ?? "—")
        case .checking:
            Label("Checking for updates…", systemImage: "arrow.triangle.2.circlepath")
        case let .upToDate(current):
            Label("Up to date — \(current)", systemImage: "checkmark.circle")
                .foregroundStyle(.green)
        case let .robotOffline(current):
            Label("\(current) — the robot can't reach the internet", systemImage: "wifi.exclamationmark")
                .foregroundStyle(.orange)
        case let .available(current, latest):
            LabeledContent("Update available") { Text("\(current) → \(latest)").monospaced() }
        case .installing:
            Label("Installing — this takes a minute or two…", systemImage: "arrow.down.circle")
        case .restarting:
            Label("The robot is restarting…", systemImage: "arrow.clockwise")
        case let .finished(version):
            Label("Updated to \(version).", systemImage: "checkmark.circle")
                .foregroundStyle(.green)
        case let .failed(message):
            Label(message, systemImage: "xmark.octagon")
                .foregroundStyle(.red)
        }
    }

    @ViewBuilder
    private var actions: some View {
        if case .available = model?.state {
            Button("Update now") {
                Task { await model?.install(preRelease: preRelease) }
            }
        } else if !(model?.isBusy ?? true) {
            Button("Check for updates") {
                Task { await model?.check(preRelease: preRelease) }
            }
        }
        if model?.log.entries.isEmpty == false {
            Button("Show installer log") { showsLog = true }
        }
    }
}

import ReachyKit
import SwiftUI

/// Everything about the connected robot that is a setting rather than a control.
///
/// Audio used to be a section of `RobotScreen` and a sheet of its own on the Live
/// tab; both now open this, so there is one place to look.
struct SettingsScreen: View {
    let session: RobotSession

    @State private var nameDraft = ""
    @State private var isRenaming = false
    @State private var renameError: String?
    @FocusState private var nameFocused: Bool

    private var identity: RobotIdentity? {
        switch session.phase {
        case let .connected(identity), let .unreachable(identity): identity
        default: nil
        }
    }

    var body: some View {
        Form {
            robotSection
            if session.isBackendRunning {
                AudioSettingsSection(session: session)
            }
            if session.supportsWirelessFeatures {
                SystemUpdateCard(session: session)
            }
        }
        .formStyle(.grouped)
        .navigationTitle("Settings")
        .onAppear { nameDraft = identity?.name ?? "" }
    }

    private var robotSection: some View {
        Section {
            HStack {
                TextField("Name", text: $nameDraft)
                    .focused($nameFocused)
                    .autocorrectionDisabled()
                    .onSubmit { rename() }
                #if os(iOS)
                    .textInputAutocapitalization(.never)
                #endif
                if isRenaming {
                    ProgressView().controlSize(.small)
                } else if canRename {
                    Button("Save", action: rename)
                        .buttonStyle(.borderless)
                }
            }
            if let renameError {
                Text(renameError)
                    .font(.caption)
                    .foregroundStyle(.red)
            }
            LabeledContent("Daemon", value: identity?.daemonVersion ?? "—")
            LabeledContent("Address", value: session.address?.displayString ?? "—")
            if let hardwareID = identity?.hardwareID {
                LabeledContent("Hardware ID", value: hardwareID)
                    .font(.body.monospaced())
            }
        } header: {
            Text("Robot")
        } footer: {
            Text("The name identifies this robot on the network. The hardware ID never changes.")
        }
    }

    private var canRename: Bool {
        let trimmed = nameDraft.trimmingCharacters(in: .whitespacesAndNewlines)
        return !trimmed.isEmpty && trimmed != identity?.name && !isRenaming
    }

    private func rename() {
        guard canRename else { return }
        let name = nameDraft.trimmingCharacters(in: .whitespacesAndNewlines)
        nameFocused = false
        isRenaming = true
        renameError = nil
        Task {
            defer { isRenaming = false }
            do {
                // The daemon may store something other than what was sent, so the
                // field follows what came back rather than what was typed.
                nameDraft = try await session.rename(to: name)
            } catch {
                renameError = (error as? LocalizedError)?.errorDescription ?? error.localizedDescription
                nameDraft = identity?.name ?? ""
            }
        }
    }
}

