import Foundation
@testable import ReachyKit
import Testing

private final class RenameStubClient: RobotAPIClient, @unchecked Sendable {
    private let lock = NSLock()
    private let stored: String?
    private var requested: [String] = []

    /// `nil` makes the daemon reject the name with a 422, as it does for an empty
    /// or over-long one.
    init(stored: String?) {
        self.stored = stored
    }

    var requestedNames: [String] {
        lock.withLock { requested }
    }

    private var status: Components.Schemas.DaemonStatus {
        let json = """
        {"robot_name": "old-name", "state": "running", "wireless_version": true,
         "desktop_app_daemon": false, "version": "1.9.0", "backend_status": null}
        """
        // swiftlint:disable:next force_try
        return try! JSONDecoder().decode(Components.Schemas.DaemonStatus.self, from: Data(json.utf8))
    }

    func handshake() async throws -> RobotConnection.Handshake {
        .init(identity: RobotIdentity(hardwareID: "hw", name: "old-name", daemonVersion: "1.9.0"), status: status)
    }

    func daemonStatus() async throws -> Components.Schemas.DaemonStatus {
        status
    }

    func wakeUp() async throws -> String { "uuid" }
    func gotoSleep() async throws -> String { "uuid" }

    func setRobotName(_ name: String) async throws -> String {
        lock.withLock { requested.append(name) }
        guard let stored else { throw ReachyKitError.daemonRejected(statusCode: 422) }
        return stored
    }
}

@MainActor
@Suite("RobotSession rename")
struct RobotSessionRenameTests {
    private func connectedSession(_ client: RenameStubClient) async -> RobotSession {
        let session = RobotSession { _ in client }
        await session.connect(to: RobotAddress(host: "10.0.0.9"))
        return session
    }

    @Test("the live identity follows what the daemon stored, not what was typed")
    func adoptsTheStoredName() async throws {
        let client = RenameStubClient(stored: "kitchen-reachy")
        let session = await connectedSession(client)

        let stored = try await session.rename(to: "Kitchen Reachy")

        #expect(stored == "kitchen-reachy")
        #expect(client.requestedNames == ["Kitchen Reachy"])
        #expect(session.phase == .connected(
            RobotIdentity(hardwareID: "hw", name: "kitchen-reachy", daemonVersion: "1.9.0")
        ))
    }

    @Test("a rejected name leaves the identity alone")
    func keepsTheOldNameOnRejection() async {
        let session = await connectedSession(RenameStubClient(stored: nil))

        await #expect(throws: ReachyKitError.daemonRejected(statusCode: 422)) {
            _ = try await session.rename(to: "")
        }
        #expect(session.phase == .connected(
            RobotIdentity(hardwareID: "hw", name: "old-name", daemonVersion: "1.9.0")
        ))
    }
}

import Foundation

/// The GATT profile `bluetooth_service.py` exposes, present since daemon 1.9.0.
///
/// Two traps live here. The robot advertises the **status** service, not the command
/// service, so scanning for `commandService` finds nothing. And it registers its
/// characteristics in reverse order — the response characteristic becomes `char1` and
/// the command characteristic `char0` — so they must be matched by UUID, never by
/// discovery order.
public enum BLEGATT {
    /// Every robot advertises this same local name, with no per-unit suffix. Two
    /// robots in range are told apart only after connecting, by `hardwareID`.
    public static let advertisedName = "ReachyMini"

    public static let commandService = "12345678-1234-5678-1234-56789abcdef0"
    public static let statusService = "12345678-1234-5678-1234-56789abcdef3"
    public static let deviceInformationService = "0000180a-0000-1000-8000-00805f9b34fb"

    /// The only service in the advertisement, so the only usable scan filter.
    public static let advertisedService = statusService
}

/// A characteristic this client reads, writes or subscribes to.
public enum BLECharacteristicID: String, CaseIterable, Sendable, Hashable {
    /// Write-with-response only. UTF-8 command strings.
    case command = "12345678-1234-5678-1234-56789abcdef1"
    /// Read and notify. Carries every reply.
    case response = "12345678-1234-5678-1234-56789abcdef2"
    /// Plain text, not JSON: `"{MODE} [iface] ip ; [iface] ip"`, or a bare `"OFFLINE"`.
    case networkStatus = "12345678-1234-5678-1234-56789abcdef4"
    case systemStatus = "12345678-1234-5678-1234-56789abcdef5"
    /// Comma-joined recovery script names, read from the robot's `commands/` directory
    /// at startup. Read it rather than hardcoding — the directory can grow.
    case availableCommands = "12345678-1234-5678-1234-56789abcdef6"
    /// `sha256(usb serial)[:16]`. The same value the daemon reports as `hardware_id`
    /// and advertises as the mDNS `unit_id`, which is how a robot provisioned over
    /// Bluetooth is recognised once it appears on the LAN.
    case hardwareID = "12345678-1234-5678-1234-56789abcdef7"

    public var service: String {
        switch self {
        case .command, .response: BLEGATT.commandService
        case .networkStatus, .systemStatus, .availableCommands, .hardwareID: BLEGATT.statusService
        }
    }
}

/// Why the central cannot be used, so the UI can say something better than a spinner.
public enum BLEAvailability: Equatable, Sendable {
    case unknown
    /// No Bluetooth hardware. This is what every iOS Simulator run reports.
    case unsupported
    case unauthorized
    case poweredOff
    case ready
}

import Foundation

/// A command written to the command characteristic as a UTF-8 string.
///
/// The robot dispatches on the *uppercased* string, except `PIN_` and `CMD_` which it
/// matches case-sensitively, and it slices arguments out of the **original-case**
/// string. So SSIDs, robot names and JSON survive verbatim even though the verb does
/// not have to be typed exactly.
public enum BLECommand: Equatable, Sendable {
    case ping
    case status
    case authenticate(pin: String)
    case wifiStatus
    case wifiScan
    case wifiKeyExchange
    case wifiConnectSealed(json: String)
    case wifiForget(ssid: String)
    case setName(String)
    case updateCheck
    case updateStart
    case updateInfo(jobID: String)
    case journalStart
    case journalRead
    case journalStop
    /// Runs `commands/<script>.sh` on the robot. Fire-and-forget: see `repliesToWrite`.
    case runScript(String)

    public var wireFormat: String {
        switch self {
        case .ping: "PING"
        case .status: "STATUS"
        case let .authenticate(pin): "PIN_\(pin)"
        case .wifiStatus: "WIFI_STATUS"
        case .wifiScan: "WIFI_SCAN"
        case .wifiKeyExchange: "WIFI_KEYEX"
        case let .wifiConnectSealed(json): "WIFI_CONNECT_ENC \(json)"
        case let .wifiForget(ssid): "WIFI_FORGET \(ssid)"
        case let .setName(name): "SET_NAME \(name)"
        case .updateCheck: "UPDATE_CHECK"
        case .updateStart: "UPDATE_START"
        case let .updateInfo(jobID): "UPDATE_INFO \(jobID)"
        case .journalStart: "JOURNAL_START"
        case .journalRead: "JOURNAL_READ"
        case .journalStop: "JOURNAL_STOP"
        case let .runScript(script): "CMD_\(script)"
        }
    }

    /// `CMD_*` returns `None` from the robot's handler on success, so the service
    /// crashes encoding the reply and the GATT write reports an error even though the
    /// script ran. Nothing can be awaited; verify by side effect instead.
    public var repliesToWrite: Bool {
        if case .runScript = self { return false }
        return true
    }

    /// Whether a live PIN session is required. `WIFI_KEYEX` is public because a bare
    /// public key is useless without the PIN, and `WIFI_STATUS` merely withholds the
    /// saved-network list from unauthenticated peers.
    public var needsSession: Bool {
        switch self {
        case .wifiScan, .wifiConnectSealed, .wifiForget, .setName,
             .updateCheck, .updateStart, .updateInfo, .runScript:
            true
        case .ping, .status, .authenticate, .wifiStatus, .wifiKeyExchange,
             .journalStart, .journalRead, .journalStop:
            false
        }
    }

    /// Commands the robot proxies to the daemon run off the BLE mainloop and answer
    /// twice — an immediate ack, then the real result as a notification. `nmcli`
    /// rescan alone can take 15 s, so these need a far longer budget than a `PING`.
    public var timeout: Duration {
        switch self {
        case .wifiScan: .seconds(30)
        case .updateCheck, .updateStart, .updateInfo: .seconds(40)
        case .wifiConnectSealed, .wifiForget, .wifiStatus, .wifiKeyExchange, .setName: .seconds(20)
        default: .seconds(5)
        }
    }

    public var data: Data {
        Data(wireFormat.utf8)
    }
}

import Foundation

/// A failure the robot reported as an `ERROR: …` string on the response
/// characteristic. Every case here is a documented string from `bluetooth_service.py`.
public enum BLECommandError: Error, Equatable, Sendable {
    /// No live PIN session — send `PIN_…` again.
    case notAuthenticated
    case incorrectPIN
    /// The wrong-PIN throttle is running. It survives a BLE disconnect, so reconnecting
    /// does not clear it; the remaining seconds are the only useful thing to show.
    case lockedOut(seconds: Int)
    /// The sealed payload would not open. Usually a wrong PIN, but also a `kid` older
    /// than the robot's 600 s key rotation — retry once with a fresh key exchange
    /// before blaming the PIN.
    case badCredentials
    /// An `nmcli` operation is already in flight (daemon 409).
    case busy
    case unknownSSID
    case cannotForgetHotspot
    /// The BLE service is up but the daemon behind it is not answering on localhost.
    case daemonUnreachable
    case invalidPayload
    case other(String)

    /// The reply is a bare string with no code, so matching is on the text the robot
    /// actually emits.
    static func parse(_ message: String) -> BLECommandError {
        if let seconds = Self.lockoutSeconds(in: message) {
            return .lockedOut(seconds: seconds)
        }
        return switch message {
        case "Not connected. Please authenticate first.": .notAuthenticated
        case "Incorrect PIN": .incorrectPIN
        case "Bad credentials (wrong PIN?)": .badCredentials
        case "Busy": .busy
        case "Unknown ssid": .unknownSSID
        case "Cannot forget hotspot": .cannotForgetHotspot
        case "Daemon unreachable": .daemonUnreachable
        case let text where text.hasPrefix("Invalid payload"), let text where text.hasPrefix("Missing field"):
            .invalidPayload
        case let text: .other(text)
        }
    }

    /// `Too many attempts. Try again in 40s.`
    private static func lockoutSeconds(in message: String) -> Int? {
        guard message.hasPrefix("Too many attempts") else { return nil }
        let digits = message.drop { !$0.isNumber }.prefix { $0.isNumber }
        return Int(digits)
    }
}

extension BLECommandError: LocalizedError {
    public var errorDescription: String? {
        switch self {
        case .notAuthenticated: "The robot needs its PIN again."
        case .incorrectPIN: "That PIN doesn't match."
        case let .lockedOut(seconds): "Too many wrong PINs. Try again in \(seconds) s."
        case .badCredentials: "The robot could not read the Wi-Fi password. Check the PIN."
        case .busy: "The robot is busy with another network operation."
        case .unknownSSID: "The robot doesn't know that network."
        case .cannotForgetHotspot: "The robot's own hotspot can't be removed."
        case .daemonUnreachable: "The robot's software isn't responding."
        case .invalidPayload: "The robot rejected the request as malformed."
        case let .other(text): text
        }
    }
}

/// One parsed reply from the response characteristic.
public enum BLEReply: Equatable, Sendable {
    case pong
    /// `OK: …` — the trailing text, e.g. `Connected` or `Named kitchen-reachy`.
    case ok(String)
    /// The robot did not recognise the command and echoed it back.
    case echo(String)
    /// A JSON document or a bare payload such as the scan result.
    case payload(String)
    case failure(BLECommandError)

    /// The synchronous ack a proxied command answers with before doing any work. The
    /// real result arrives later as a notification, so this value is never a result.
    public static let workingAck = "OK: working"

    public var isWorkingAck: Bool {
        self == .ok("working")
    }

    /// Non-nil for `.payload`, and for `.ok` whose text is itself the answer.
    public var text: String? {
        switch self {
        case let .payload(text), let .ok(text), let .echo(text): text
        case .pong: "PONG"
        case .failure: nil
        }
    }
}

public enum BLEResponseParser {
    public static func parse(_ raw: String) -> BLEReply {
        let text = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        if text == "PONG" {
            return .pong
        }
        if let body = text.dropPrefix("ERROR: ") {
            return .failure(.parse(body))
        }
        if let body = text.dropPrefix("OK: ") {
            return .ok(body)
        }
        if let body = text.dropPrefix("ECHO: ") {
            return .echo(body)
        }
        return .payload(text)
    }

    public static func parse(_ data: Data) -> BLEReply {
        guard let text = String(bytes: data, encoding: .utf8) else {
            return .failure(.other("The robot sent a reply this app could not read."))
        }
        return parse(text)
    }
}

private extension String {
    func dropPrefix(_ prefix: String) -> String? {
        hasPrefix(prefix) ? String(dropFirst(prefix.count)) : nil
    }
}

import Foundation

/// Tracks the robot's PIN session and its wrong-PIN throttle, which have different
/// lifetimes and are easy to conflate.
///
/// The session is a 300 s window the robot opens on a correct `PIN_…` and **drops the
/// moment BLE disconnects**. The throttle is robot-global, counts wrong attempts, and
/// **survives a disconnect** — during a lockout the robot does not even compare the
/// PIN, so a correct one still fails. Reconnecting therefore clears the permission but
/// not the penalty.
public struct BLEPinSession: Equatable, Sendable {
    /// `SESSION_TTL_S` in `bluetooth_service.py`.
    public static let ttl: Duration = .seconds(300)
    /// `PIN_FREE_ATTEMPTS`, `PIN_LOCKOUT_BASE_S`, `PIN_LOCKOUT_MAX_S`.
    public static let freeAttempts = 3

    private var authenticatedUntil: ContinuousClock.Instant?
    private var lockedOutUntil: ContinuousClock.Instant?
    public private(set) var failures = 0

    public init() {}

    public func isAuthenticated(at now: ContinuousClock.Instant = .now) -> Bool {
        guard let authenticatedUntil else { return false }
        return now < authenticatedUntil
    }

    /// Seconds left on the throttle, or nil when it is not running. The robot reports
    /// this itself; this is the local mirror so a countdown can tick between replies.
    public func lockoutRemaining(at now: ContinuousClock.Instant = .now) -> Duration? {
        guard let lockedOutUntil, now < lockedOutUntil else { return nil }
        return now.duration(to: lockedOutUntil)
    }

    public var attemptsBeforeLockout: Int {
        max(0, Self.freeAttempts - failures)
    }

    public mutating func authenticated(at now: ContinuousClock.Instant = .now) {
        authenticatedUntil = now.advanced(by: Self.ttl)
        lockedOutUntil = nil
        failures = 0
    }

    public mutating func failed(at now: ContinuousClock.Instant = .now) {
        failures += 1
        authenticatedUntil = nil
    }

    /// Applied from the robot's own `Try again in <n>s` reply, which is authoritative —
    /// the counter is robot-global and may already have been advanced by another phone.
    public mutating func lockedOut(for seconds: Int, at now: ContinuousClock.Instant = .now) {
        failures = max(failures, Self.freeAttempts + 1)
        authenticatedUntil = nil
        lockedOutUntil = now.advanced(by: .seconds(seconds))
    }

    /// Drops the session and **keeps the lockout**. This asymmetry is the whole point
    /// of the type: offering an immediate retry after a reconnect would walk the user
    /// straight into a refusal the robot never even evaluates.
    public mutating func invalidateOnDisconnect() {
        authenticatedUntil = nil
    }
}

import Foundation

/// The network-status characteristic, which is plain text rather than JSON:
/// `"{MODE} [iface] ip ; [iface] ip"`, or a bare `"OFFLINE"` when the robot has no
/// interfaces at all.
///
/// This is the live address, unlike the Device Information "firmware revision"
/// characteristic, which the robot abuses to carry `"[HOTSPOT]:<ip>"` and never
/// refreshes after boot.
public struct WiFiNetworkStatus: Equatable, Sendable {
    public enum Mode: String, Equatable, Sendable {
        case hotspot = "HOTSPOT"
        case connected = "CONNECTED"
        case offline = "OFFLINE"
        case error = "ERROR"
    }

    public struct Interface: Equatable, Sendable {
        public let name: String
        public let address: String
    }

    public let mode: Mode
    public let interfaces: [Interface]

    /// The address to reach the daemon on. In hotspot mode this is the well-known
    /// `10.42.0.1`; on a joined network it is whatever DHCP handed out.
    public var address: String? {
        interfaces.first { $0.name == "wlan0" }?.address ?? interfaces.first?.address
    }

    public init?(parsing raw: String) {
        let text = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else { return nil }

        let head = text.prefix { $0 != "[" }.trimmingCharacters(in: .whitespaces)
        guard let mode = Mode(rawValue: head) else { return nil }
        self.mode = mode

        interfaces = text
            .dropFirst(head.count)
            .split(separator: ";")
            .compactMap(Self.interface(in:))
    }

    /// One `"[wlan0] 192.168.1.42"` segment.
    private static func interface(in segment: some StringProtocol) -> Interface? {
        let trimmed = segment.trimmingCharacters(in: .whitespaces)
        guard trimmed.hasPrefix("["), let close = trimmed.firstIndex(of: "]") else { return nil }
        let name = String(trimmed[trimmed.index(after: trimmed.startIndex) ..< close])
        let address = trimmed[trimmed.index(after: close)...].trimmingCharacters(in: .whitespaces)
        guard !name.isEmpty, !address.isEmpty else { return nil }
        return Interface(name: name, address: address)
    }
}

import Foundation

/// The robot's Wi-Fi state, as reported by both `WIFI_STATUS` over BLE and
/// `GET /wifi/status` over HTTP.
public struct WiFiStatus: Equatable, Sendable, Decodable {
    public enum Mode: String, Equatable, Sendable {
        case hotspot
        case wlan
        case disconnected
        /// An `nmcli` operation is in flight. Transient — keep polling.
        case busy
    }

    /// Nil when the BLE service could not reach the daemon at all.
    public let mode: Mode?
    /// The SSID the robot has actually joined.
    public let connected: String?
    /// Saved networks. Withheld from unauthenticated peers, because the list of
    /// networks a robot knows is a fingerprint of where its owner lives.
    public let known: [String]?
    public let error: String?

    public init(mode: Mode?, connected: String?, known: [String]? = nil, error: String? = nil) {
        self.mode = mode
        self.connected = connected
        self.known = known
        self.error = error
    }

    public func hasJoined(_ ssid: String) -> Bool {
        mode == .wlan && connected == ssid && error == nil
    }

    /// A failed join drops the robot back onto its own access point, so this is what
    /// "the password was wrong" looks like from the client side.
    public var didFallBackToHotspot: Bool {
        mode == .hotspot
    }

    private enum CodingKeys: String, CodingKey {
        case mode, connected, known, error
        // `GET /wifi/status` spells the same two fields differently from the BLE relay.
        case knownNetworks = "known_networks"
        case connectedNetwork = "connected_network"
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        // An unrecognised mode decodes to nil rather than throwing: the daemon versions
        // independently, and a new state must not break a status poll mid-provisioning.
        mode = try container.decodeIfPresent(String.self, forKey: .mode).flatMap(Mode.init(rawValue:))
        connected = try container.decodeIfPresent(String.self, forKey: .connected)
            ?? container.decodeIfPresent(String.self, forKey: .connectedNetwork)
        known = try container.decodeIfPresent([String].self, forKey: .known)
            ?? container.decodeIfPresent([String].self, forKey: .knownNetworks)
        error = try container.decodeIfPresent(String.self, forKey: .error)
    }
}

/// The robot's ephemeral key for sealing a Wi-Fi password, from `WIFI_KEYEX` or
/// `GET /wifi/prov_key`.
public struct WiFiProvisioningKey: Equatable, Sendable, Decodable {
    /// Key id. The robot rotates its keypair every 600 s and rejects a stale one.
    public let kid: String
    /// Base64 of the raw 32-byte X25519 public key.
    public let pk: String
    public let alg: String

    public init(kid: String, pk: String, alg: String = WiFiPasswordSeal.algorithm) {
        self.kid = kid
        self.pk = pk
        self.alg = alg
    }
}

/// The `WIFI_CONNECT_ENC` / `POST /wifi/connect_sealed` payload.
public struct SealedWiFiCredentials: Equatable, Sendable, Encodable {
    public let ssid: String
    public let kid: String
    /// Base64 of this client's raw 32-byte ephemeral X25519 public key.
    public let epk: String
    /// Base64 of the 12-byte AES-GCM nonce.
    public let nonce: String
    /// Base64 of `ciphertext ‖ 16-byte tag`. CryptoKit keeps them apart; Python's
    /// `AESGCM.decrypt` expects them joined.
    public let ct: String

    /// The robot's field names are fixed by its Pydantic model, so the JSON is emitted
    /// as-is with no key strategy.
    public func jsonString() throws -> String {
        let data = try JSONEncoder().encode(self)
        guard let json = String(bytes: data, encoding: .utf8) else {
            throw ReachyKitError.daemonRejected(statusCode: -1)
        }
        return json
    }
}

import CryptoKit
import Foundation

/// Seals a Wi-Fi password so it never crosses Bluetooth in the clear.
///
/// Mirrors the daemon's `x25519-hkdf-sha256-aesgcm` scheme byte for byte — salt, info
/// label and AAD all take part in the key, so any drift fails as an authentication
/// error rather than as garbage.
///
/// **Known limitation, inherited from upstream and documented there.** This protects
/// the password from a passive listener, but not from an active man-in-the-middle
/// present during the few seconds of setup: it would answer the key exchange with its
/// own public key and could then brute-force the 5-character PIN offline. Upstream
/// tracks a PAKE as the fix. Provisioning should happen somewhere the user trusts.
public enum WiFiPasswordSeal {
    public static let algorithm = "x25519-hkdf-sha256-aesgcm"
    /// Byte-for-byte identical to the daemon's HKDF `info`.
    static let info = Data("reachy-mini-wifi-psk-v1".utf8)

    public enum Failure: Error, Equatable {
        case malformedRobotKey
        case unsupportedAlgorithm(String)
    }

    /// `ephemeralPrivateKey` and `nonce` exist only so a test can reproduce a known
    /// ciphertext. Production always takes the random defaults.
    public static func seal(
        ssid: String,
        password: String,
        pin: String,
        key: WiFiProvisioningKey,
        ephemeralPrivateKey: Curve25519.KeyAgreement.PrivateKey = .init(),
        nonce: AES.GCM.Nonce? = nil
    ) throws -> SealedWiFiCredentials {
        guard key.alg == algorithm else {
            throw Failure.unsupportedAlgorithm(key.alg)
        }
        guard let raw = Data(base64Encoded: key.pk),
              let robotPublicKey = try? Curve25519.KeyAgreement.PublicKey(rawRepresentation: raw)
        else {
            throw Failure.malformedRobotKey
        }

        let shared = try ephemeralPrivateKey.sharedSecretFromKeyAgreement(with: robotPublicKey)
        // The PIN is the HKDF salt: knowing the key exchange alone is not enough to
        // open the password.
        let symmetricKey = shared.hkdfDerivedSymmetricKey(
            using: SHA256.self,
            salt: Data(pin.utf8),
            sharedInfo: info,
            outputByteCount: 32
        )

        // The SSID as AAD binds the sealed password to its target network, so a
        // captured blob cannot be replayed against a different one.
        let sealed = try AES.GCM.seal(
            Data(password.utf8),
            using: symmetricKey,
            nonce: nonce,
            authenticating: Data(ssid.utf8)
        )

        return SealedWiFiCredentials(
            ssid: ssid,
            kid: key.kid,
            epk: ephemeralPrivateKey.publicKey.rawRepresentation.base64EncodedString(),
            nonce: Data(sealed.nonce).base64EncodedString(),
            ct: (sealed.ciphertext + sealed.tag).base64EncodedString()
        )
    }
}

import CryptoKit
import Foundation
@testable import ReachyKit
import Testing

/// The sealed password is the one thing here with no feedback loop: if the derivation
/// drifts by a byte the robot answers `ERROR: Bad credentials (wrong PIN?)`, which
/// reads exactly like the user mistyping the PIN. So it is pinned against a vector
/// produced by the *daemon's* library — see `Scripts/generate-seal-fixture.py`.
@Suite("WiFiPasswordSeal")
struct WiFiPasswordSealTests {
    private struct Vector: Decodable {
        let ssid: String
        let password: String
        let pin: String
        let kid: String
        let robotPublicKey: String
        let clientPrivateKey: String
        let nonce: String
        let expectedClientPublicKey: String
        let expectedCiphertext: String
    }

    private func loadVector() throws -> Vector {
        let url = try #require(Bundle.module.url(forResource: "wifi_seal_vector", withExtension: "json"))
        return try JSONDecoder().decode(Vector.self, from: Data(contentsOf: url))
    }

    private func seal(_ vector: Vector, ssid: String? = nil) throws -> SealedWiFiCredentials {
        try WiFiPasswordSeal.seal(
            ssid: ssid ?? vector.ssid,
            password: vector.password,
            pin: vector.pin,
            key: WiFiProvisioningKey(kid: vector.kid, pk: vector.robotPublicKey),
            ephemeralPrivateKey: Curve25519.KeyAgreement.PrivateKey(
                rawRepresentation: try #require(Data(base64Encoded: vector.clientPrivateKey))
            ),
            nonce: try AES.GCM.Nonce(data: #require(Data(base64Encoded: vector.nonce)))
        )
    }

    @Test("reproduces a ciphertext the daemon's own library produced")
    func matchesTheKnownAnswer() throws {
        let vector = try loadVector()

        let sealed = try seal(vector)

        #expect(sealed.epk == vector.expectedClientPublicKey)
        #expect(sealed.nonce == vector.nonce)
        #expect(sealed.ct == vector.expectedCiphertext)
        #expect(sealed.ssid == vector.ssid)
        #expect(sealed.kid == vector.kid)
    }

    @Test("the tag is appended to the ciphertext, which CryptoKit keeps separate")
    func appendsTheAuthenticationTag() throws {
        let vector = try loadVector()

        let sealed = try seal(vector)
        let raw = try #require(Data(base64Encoded: sealed.ct))

        #expect(raw.count == vector.password.utf8.count + 16)
    }

    @Test("base64 is standard, not URL-safe — the daemon decodes with b64decode")
    func usesStandardBase64() throws {
        let vector = try loadVector()

        let sealed = try seal(vector)

        for field in [sealed.epk, sealed.nonce, sealed.ct] {
            #expect(!field.contains("-"))
            #expect(!field.contains("_"))
            #expect(Data(base64Encoded: field) != nil)
        }
    }

    @Test("the SSID is bound into the ciphertext, so a captured blob can't target another network")
    func bindsTheSSIDAsAAD() throws {
        let vector = try loadVector()

        let sealed = try seal(vector)
        let other = try seal(vector, ssid: "Someone Else's Net")

        #expect(sealed.ct != other.ct)
    }

    @Test("a robot key that is not a 32-byte X25519 point is rejected before anything is sent")
    func rejectsAMalformedRobotKey() {
        #expect(throws: WiFiPasswordSeal.Failure.malformedRobotKey) {
            try WiFiPasswordSeal.seal(
                ssid: "net",
                password: "pw",
                pin: "12345",
                key: WiFiProvisioningKey(kid: "k", pk: "not base64 at all")
            )
        }
        #expect(throws: WiFiPasswordSeal.Failure.malformedRobotKey) {
            try WiFiPasswordSeal.seal(
                ssid: "net",
                password: "pw",
                pin: "12345",
                key: WiFiProvisioningKey(kid: "k", pk: Data(repeating: 0x41, count: 16).base64EncodedString())
            )
        }
    }

    @Test("an algorithm this client does not implement is refused rather than guessed at")
    func rejectsAnUnknownAlgorithm() throws {
        let vector = try loadVector()

        #expect(throws: WiFiPasswordSeal.Failure.unsupportedAlgorithm("kyber-something")) {
            try WiFiPasswordSeal.seal(
                ssid: vector.ssid,
                password: vector.password,
                pin: vector.pin,
                key: WiFiProvisioningKey(kid: vector.kid, pk: vector.robotPublicKey, alg: "kyber-something")
            )
        }
    }

    /// RFC 5869 test case 1. If CryptoKit's HKDF ever changes shape this fails by
    /// name, instead of surfacing as an unexplained ciphertext mismatch above.
    @Test("CryptoKit's HKDF still matches RFC 5869")
    func hkdfMatchesTheStandard() throws {
        let shared = SharedSecret.self // documents intent; the KAT uses the raw HKDF below
        _ = shared

        let derived = HKDF<SHA256>.deriveKey(
            inputKeyMaterial: SymmetricKey(data: Data(repeating: 0x0B, count: 22)),
            salt: Data((0x00 ... 0x0C).map(UInt8.init)),
            info: Data((0xF0 ... 0xF9).map(UInt8.init)),
            outputByteCount: 42
        )
        let expected = """
        3cb25f25faacd57a90434f64d0362f2a2d2d0a90cf1a5a4c5db02d56ecc4c5bf34007208d5b887185865
        """

        let hex = derived.withUnsafeBytes { Data($0) }.map { String(format: "%02x", $0) }.joined()
        #expect(hex == expected)
    }
}

