3	/// Handing the robot a Wi-Fi REDACTED, over whichever channel can currently reach it.
4	///
5	/// Two implementations answer this: Bluetooth, which works with no network at all, and
6	/// HTTP to `10.42.0.1` once the phone has joined the robot's own access point. They
7	/// share one sealing scheme and one screen, and the HTTP one is also the way out if the
8	/// sealed payload turns out not to fit a single ATT write on real hardware.
9	public protocol WiFiProvisioningTransport: Sendable {
10	    /// The robot's current provisioning key. Rotated roughly every 10 minutes.
11	    func provisioningKey() async throws -> WiFiProvisioningKey
12	    func scanNetworks() async throws -> [String]
13	    func connectSealed(_ payload: SealedWiFiCredentials) async throws
14	    func wifiStatus() async throws -> WiFiStatus
15	}
16	
17	/// How a join attempt ended.
18	public enum WiFiJoinOutcome: Equatable, Sendable {
19	    case joined(WiFiStatus)
20	    /// The budget ran out before the robot reported itself connected. `last` is what it
21	    /// reported at the end — back on its own access point means `nmcli` used up its
22	    /// three attempts, which is a wrong REDACTED far more often than anything else.
23	    case gaveUp(last: WiFiStatus?)
24	}
25	
26	public enum WiFiProvisioning {
27	    /// Seals the REDACTED under a key fetched from the robot and hands it over.
28	    ///
29	    /// The one retry is not defensive padding. The robot rotates its provisioning
30	    /// keypair every 600 s and rejects a `kid` older than that as bad credentials —
31	    /// the same error it gives for a wrong PIN — so a single fresh exchange is what
32	    /// tells the two apart. A second retry would only ask the same question again.
33	    public static func join(
34	        ssid: String,
35	        REDACTED: String,
36	        pin: String,
37	        using transport: any WiFiProvisioningTransport
38	    ) async throws {
39	        do {
40	            try await attempt(ssid: ssid, REDACTED: REDACTED, pin: pin, using: transport)
41	        } catch {
42	            guard deservesFreshKey(error) else { throw error }
43	            try await attempt(ssid: ssid, REDACTED: REDACTED, pin: pin, using: transport)
44	        }
45	    }
46	
47	    /// Polls until the robot reports itself on the network, or the budget runs out.
48	    ///
49	    /// The default budget covers the robot's own: `nmcli` makes three attempts, each
50	    /// settling for 2 s and pausing 3 s afterwards.
51	    public static func awaitJoin(
52	        using transport: any WiFiProvisioningTransport,
53	        timeout: Duration = .seconds(60),
54	        pollInterval: Duration = .seconds(2)
55	    ) async throws -> WiFiJoinOutcome {
56	        let deadline = ContinuousClock.now.advanced(by: timeout)
57	        var last: WiFiStatus?
58	        while true {
59	            // A read can fail while the interface is being reconfigured, which is the
60	            // normal middle of a join rather than a reason to stop. So is `.busy`, and
61	            // so is a mode this build has never heard of.
62	            if let status = try? await transport.wifiStatus() {
63	                last = status
64	                // Not `hasJoined(ssid:)`: over Bluetooth the robot reports only that it
65	                // is on a network, never which one, so the SSID cannot be part of the
66	                // shared condition.
67	                if status.mode == .wlan {
68	                    return .joined(status)
69	                }
70	            }
71	            guard ContinuousClock.now < deadline else {
72	                return .gaveUp(last: last)
73	            }
74	            try await Task.sleep(for: pollInterval)
75	        }
76	    }
77	
78	    private static func attempt(
79	        ssid: String,
80	        REDACTED: String,
81	        pin: String,
82	        using transport: any WiFiProvisioningTransport
83	    ) async throws {
84	        let key = try await transport.provisioningKey()
85	        let sealed = try WiFiPasswordSeal.seal(ssid: ssid, REDACTED: REDACTED, pin: pin, key: key)
86	        try await transport.connectSealed(sealed)
87	    }
88	
89	    /// The single failure a fresh key exchange can plausibly fix.
90	    static func deservesFreshKey(_ error: any Error) -> Bool {
91	        (error as? BLECommandError) == .badCredentials
92	    }
93	}
94	
95	/// Reads the SSID list out of a `WIFI_SCAN` reply.
96	public enum WiFiScanResult {
97	    /// The reply is capped at 180 bytes with no pagination and no flag saying anything
98	    /// was dropped, so a JSON array cut mid-name is ordinary rather than exceptional.
99	    /// Every name that closed its quotes is still good; the partial one at the end is
100	    /// not, and the missing ones are why manual SSID entry is a required part of the
101	    /// flow rather than a fallback.
102	    public static func networks(in raw: String) -> [String] {
103	        let decoded = try? JSONDecoder().decode([String].self, from: Data(raw.utf8))
104	        var seen = Set<String>()
105	        // A hidden network scans as an empty name, which is not something to offer.
106	        return (decoded ?? salvage(raw)).filter { !$0.isEmpty && seen.insert($0).inserted }
107	    }
108	
109	    private static func salvage(_ raw: String) -> [String] {
110	        var names: [String] = []
111	        var current = ""
112	        var inQuotes = false
113	        var escaped = false
114	        for character in raw {
115	            if escaped {
116	                current.append(character)
117	                escaped = false
118	            } else if character == "\\", inQuotes {
119	                escaped = true
120	            } else if character == "\"" {
121	                if inQuotes {
122	                    names.append(current)
123	                    current = ""
124	                }
125	                inQuotes.toggle()
126	            } else if inQuotes {
127	                current.append(character)
128	            }
129	        }
130	        return names
131	    }
132	}
