3	/// A failure the robot reported as an `ERROR: …` string on the response
4	/// characteristic. Every case here is a documented string from `bluetooth_service.py`.
5	public enum BLECommandError: Error, Equatable, Sendable {
6	    /// No live PIN session — send `PIN_…` again.
7	    case notAuthenticated
8	    case incorrectPIN
9	    /// The wrong-PIN throttle is running. It survives a BLE disconnect, so reconnecting
10	    /// does not clear it; the remaining seconds are the only useful thing to show.
11	    case lockedOut(seconds: Int)
12	    /// The sealed payload would not open. Usually a wrong PIN, but also a `kid` older
13	    /// than the robot's 600 s key rotation — retry once with a fresh key exchange
14	    /// before blaming the PIN.
15	    case badCredentials
16	    /// An `nmcli` operation is already in flight (daemon 409).
17	    case busy
18	    case unknownSSID
19	    case cannotForgetHotspot
20	    /// The BLE service is up but the daemon behind it is not answering on localhost.
21	    case daemonUnreachable
22	    case invalidPayload
23	    case other(String)
24	
25	    /// The reply is a bare string with no code, so matching is on the text the robot
26	    /// actually emits.
27	    static func parse(_ message: String) -> BLECommandError {
28	        if let seconds = lockoutSeconds(in: message) {
29	            return .lockedOut(seconds: seconds)
30	        }
31	        return switch message {
32	        case "Not connected. Please authenticate first.": .notAuthenticated
33	        case "Incorrect PIN": .incorrectPIN
34	        case "Bad credentials (wrong PIN?)": .badCredentials
35	        case "Busy": .busy
36	        case "Unknown ssid": .unknownSSID
37	        case "Cannot forget hotspot": .cannotForgetHotspot
38	        case "Daemon unreachable": .daemonUnreachable
39	        case let text where text.hasPrefix("Invalid payload"), let text where text.hasPrefix("Missing field"):
40	            .invalidPayload
41	        case let text: .other(text)
42	        }
43	    }
44	
45	    /// `Too many attempts. Try again in 40s.`
46	    private static func lockoutSeconds(in message: String) -> Int? {
47	        guard message.hasPrefix("Too many attempts") else { return nil }
48	        let digits = message.drop { !$0.isNumber }.prefix { $0.isNumber }
49	        return Int(digits)
50	    }
51	}
52	
53	extension BLECommandError: LocalizedError {
54	    public var errorDescription: String? {
55	        switch self {
56	        case .notAuthenticated: "The robot needs its PIN again."
57	        case .incorrectPIN: "That PIN doesn't match."
58	        case let .lockedOut(seconds): "Too many wrong PINs. Try again in \(seconds) s."
59	        case .badCredentials: "The robot could not read the Wi-Fi password. Check the PIN."
60	        case .busy: "The robot is busy with another network operation."
61	        case .unknownSSID: "The robot doesn't know that network."
62	        case .cannotForgetHotspot: "The robot's own hotspot can't be removed."
63	        case .daemonUnreachable: "The robot's software isn't responding."
64	        case .invalidPayload: "The robot rejected the request as malformed."
65	        case let .other(text): text
66	        }
67	    }
68	}
69	
70	/// One parsed reply from the response characteristic.
71	public enum BLEReply: Equatable, Sendable {
72	    case pong
73	    /// `OK: …` — the trailing text, e.g. `Connected` or `Named kitchen-reachy`.
74	    case ok(String)
75	    /// The robot did not recognise the command and echoed it back.
76	    case echo(String)
77	    /// A JSON document or a bare payload such as the scan result.
78	    case payload(String)
