239	    /// Records a discovered characteristic and, once every requested service has
240	    /// reported, finishes the connection.
241	    func absorb(_ discovered: [CBCharacteristic]) {
242	        // Matched by UUID because the robot registers its characteristics in reverse
243	        // order, so discovery order says nothing about which is which.
244	        for characteristic in discovered
245	            where BLECharacteristicID(rawValue: characteristic.uuid.uuidString.lowercased()) != nil
246	        {
247	            characteristics[characteristic.uuid] = characteristic
248	        }
249	        undiscoveredServices -= 1
250	        guard undiscoveredServices <= 0, let pending = pendingConnect else { return }
251	        pendingConnect = nil
252	        let missing = [BLECharacteristicID.command, .response]
253	            .first { characteristics[Self.key($0)] == nil }
254	        if let missing {
255	            pending.resume(throwing: BLETransportError.characteristicMissing(missing))
256	            return
257	        }
