280	        connected = nil
281	        undiscoveredServices = 0
282	        publish { $0.maximumWriteLength = Self.minimumWriteLength }
283	
284	        pendingConnect?.resume(throwing: BLETransportError.connectionFailed(reason ?? "The robot disconnected."))
285	        pendingConnect = nil
286	        for continuation in pendingWrites.values {
287	            continuation.resume(throwing: BLETransportError.notConnected)
288	        }
289	        pendingWrites = [:]
290	        for continuation in pendingReads.values {
291	            continuation.resume(throwing: BLETransportError.notConnected)
292	        }
293	        pendingReads = [:]
294	        for continuation in pendingNotifies.values {
295	            continuation.resume(throwing: BLETransportError.notConnected)
296	        }
297	        pendingNotifies = [:]
298	        // Ends the pump's wait, which then falls back to a read and reports the drop
299	        // rather than sitting out its timeout.
300	        for listener in notificationListeners.values {
301	            listener.finish()
302	        }
303	        notificationListeners = [:]
