308	    /// Runs `start` on the queue, waits for a delegate callback to resume it, and runs
309	    /// `expire` on the same queue if that never happens. Both sides mutate the pending
310	    /// slot from one serial queue, so the losing side finds it already gone and cannot
311	    /// resume a second time.
312	    private func awaitingReply<T: Sendable>(
313	        timeout: Duration,
314	        start: @escaping @Sendable (CheckedContinuation<T, any Error>) -> Void,
315	        expire: @escaping @Sendable () -> Void
316	    ) async throws -> T {
317	        let expiry = Task { [queue] in
318	            try? await Task.sleep(for: timeout)
319	            guard !Task.isCancelled else { return }
320	            queue.async(execute: expire)
321	        }
322	        defer { expiry.cancel() }
323	        return try await withCheckedThrowingContinuation { continuation in
324	            queue.async { start(continuation) }
325	        }
326	    }
