62	        let (stream, continuation) = AsyncStream.makeStream(of: Data.self)
63	        lock.withLock { self.continuation = continuation }
64	        return stream
65	    }
66	
67	    func events() -> AsyncStream<BLETransportEvent> {
68	        let (stream, continuation) = AsyncStream.makeStream(of: BLETransportEvent.self)
69	        lock.withLock { self.eventContinuation = continuation }
70	        return stream
