89	        if writeDelay > .zero {
90	            try? await Task.sleep(for: writeDelay)
91	        }
92	
93	        let script = lock.withLock { scripts[command] }
94	        lock.withLock {
95	            writeInFlight = false
96	            lastRead = script?.read ?? "ECHO: \(command)"
97	        }
98	        guard let script, let notify = script.notify, !script.dropsNotification else { return }
99	        // A real notification never lands before the write completes.
100	        Task { [weak self] in
101	            guard let self else { return }
102	            let continuation = lock.withLock { self.continuation }
103	            lock.withLock { self.lastRead = notify }
104	            continuation?.yield(Data(notify.utf8))
