import ReachyKit
import SwiftUI

/// First-run setup over Bluetooth: Welcome → Scan → PIN → Network → Joining → Naming →
/// Handoff.
///
/// A sheet rather than a navigation route, because it owns a radio link that has to come
/// down however the user leaves — and because it is never something the app waits on.
struct OnboardingFlow: View {
    var onFinish: (OnboardingOutcome) -> Void
    var onCancel: () -> Void

    @State private var model = OnboardingModel()

    var body: some View {
        NavigationStack {
            step
                .navigationTitle("Set up a robot")
                .toolbarTitleStyle()
                .toolbar {
                    ToolbarItem(placement: .cancellationAction) {
                        Button("Cancel") {
                            model.cancel()
                            onCancel()
                        }
                    }
                }
        }
    }

    @ViewBuilder
    private var step: some View {
        switch model.step {
        case .welcome:
            OnboardingWelcomeStep(model: model)
        case .scan:
            OnboardingScanStep(model: model)
        case .pin:
            OnboardingPINStep(model: model)
        case .network:
            OnboardingNetworkStep(model: model)
        case .joining:
            OnboardingJoinStep(model: model)
        case .naming:
            OnboardingNamingStep(model: model)
        case .handoff:
            OnboardingHandoffStep(model: model, onFinish: onFinish)
        }
    }
}

/// The shape every step shares: one heading, one explanation, whatever the step needs in
/// the middle, and its actions pinned to the bottom where a thumb is.
struct OnboardingStepScaffold<Content: View, Actions: View>: View {
    let title: String
    let message: String
    var back: (() -> Void)?
    @ViewBuilder var content: () -> Content
    @ViewBuilder var actions: () -> Actions

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 16) {
                Text(title)
                    .font(.title2.bold())
                Text(message)
                    .foregroundStyle(.secondary)
                    .fixedSize(horizontal: false, vertical: true)
                content()
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding()
        }
        .safeAreaInset(edge: .bottom) {
            VStack(spacing: 8) {
                actions()
                if let back {
                    Button("Back", action: back)
                        .buttonStyle(.plain)
                        .foregroundStyle(.secondary)
                }
            }
            .padding()
            .frame(maxWidth: .infinity)
            .background(.bar)
        }
    }
}

/// The error the current step ran into, if any. Steps that can also fail structurally
/// (a refused join, a lockout) say so in their own words instead.
struct OnboardingErrorText: View {
    let message: String?

    var body: some View {
        if let message {
            Label(message, systemImage: "exclamationmark.triangle")
                .font(.callout)
                .foregroundStyle(.red)
                .fixedSize(horizontal: false, vertical: true)
        }
    }
}

private extension View {
    func toolbarTitleStyle() -> some View {
        #if os(iOS)
            navigationBarTitleDisplayMode(.inline)
        #else
            self
        #endif
    }
}

import SwiftUI

/// Stands between opening the flow and the first CoreBluetooth call, so the system's
/// Bluetooth prompt arrives on a screen that has already said what it is for.
struct OnboardingWelcomeStep: View {
    let model: OnboardingModel

    var body: some View {
        OnboardingStepScaffold(
            title: "Before you start",
            message: "A new robot has no network yet, so the first conversation happens over Bluetooth. "
                + "It takes a couple of minutes."
        ) {
            VStack(alignment: .leading, spacing: 14) {
                requirement(
                    "The robot, powered on",
                    detail: "Give it about a minute after switching on before it starts advertising.",
                    icon: "power"
                )
                requirement(
                    "The five-character code from its base",
                    detail: "Printed underneath. It is case-sensitive, and it is not always digits.",
                    icon: "numbers.rectangle"
                )
                requirement(
                    "Your Wi-Fi password",
                    detail: "It is encrypted for the robot before it leaves this device.",
                    icon: "wifi"
                )
                Label(
                    "The next screen turns on Bluetooth scanning, so iOS will ask for permission.",
                    systemImage: "info.circle"
                )
                .font(.footnote)
                .foregroundStyle(.secondary)
            }
        } actions: {
            Button("Start") {
                model.beginScan()
            }
            .buttonStyle(.borderedProminent)
            .frame(maxWidth: .infinity)
        }
    }

    private func requirement(_ title: String, detail: String, icon: String) -> some View {
        Label {
            VStack(alignment: .leading, spacing: 2) {
                Text(title)
                Text(detail)
                    .font(.footnote)
                    .foregroundStyle(.secondary)
            }
        } icon: {
            Image(systemName: icon)
                .foregroundStyle(.tint)
        }
        .fixedSize(horizontal: false, vertical: true)
    }
}

import ReachyKit
import SwiftUI

/// Picks one robot out of everything advertising the provisioning service.
///
/// Every robot advertises the same local name, so the list is ordered by signal strength
/// and says so — until one is connected there is nothing else to tell them apart by.
struct OnboardingScanStep: View {
    let model: OnboardingModel

    var body: some View {
        OnboardingStepScaffold(
            title: "Find the robot",
            message: message,
            back: { model.back() }
        ) {
            switch model.availability {
            case .ready, .unknown:
                results
            case .poweredOff:
                unavailable(
                    "Bluetooth is switched off",
                    detail: "Turn it on in Control Centre or Settings, and this list will fill in."
                )
            case .unauthorized:
                unavailable(
                    "This app can't use Bluetooth",
                    detail: "Allow Bluetooth for this app in Settings, then come back."
                )
                #if os(iOS)
                    Button("Open Settings") {
                        if let url = URL(string: UIApplication.openSettingsURLString) {
                            UIApplication.shared.open(url)
                        }
                    }
                #endif
            case .unsupported:
                unavailable(
                    "This device has no Bluetooth",
                    detail: "The iOS Simulator never has any. Set the robot up from a real device, or join "
                        + "its own reachy-mini-ap network and configure it over Wi-Fi instead."
                )
            }
            OnboardingErrorText(message: model.errorMessage)
        } actions: {
            if let only = model.discovered.first, model.discovered.count == 1 {
                Button("Connect to this robot") {
                    Task { await model.connect(to: only.id) }
                }
                .buttonStyle(.borderedProminent)
                .frame(maxWidth: .infinity)
                .disabled(model.isBusy)
            }
        }
    }

    private var message: String {
        switch model.availability {
        case .ready, .unknown:
            "Robots all advertise the same name, so they are listed by signal strength. "
                + "The nearest one is at the top."
        default:
            "Setting a robot up needs Bluetooth."
        }
    }

    @ViewBuilder
    private var results: some View {
        if model.discovered.isEmpty {
            HStack(spacing: 10) {
                ProgressView()
                Text("Searching…")
                    .foregroundStyle(.secondary)
            }
        }
        ForEach(model.discovered) { robot in
            Button {
                Task { await model.connect(to: robot.id) }
            } label: {
                LabeledContent {
                    if model.isBusy {
                        ProgressView()
                    } else {
                        Text("\(robot.rssi) dBm")
                            .font(.caption.monospaced())
                    }
                } label: {
                    Label(robot.name, systemImage: "dot.radiowaves.left.and.right")
                }
            }
            .buttonStyle(.bordered)
            .disabled(model.isBusy)
        }
    }

    private func unavailable(_ title: String, detail: String) -> some View {
        ContentUnavailableView(title, systemImage: "antenna.radiowaves.left.and.right.slash", description: Text(detail))
    }
}

import ReachyKit
import SwiftUI

/// Unlocks the robot's 300-second session with the code printed on its base.
///
/// The wrong-code throttle is the robot's, not this screen's: it is global to the robot
/// and survives a reconnect, so during a lockout there is nothing to do but wait it out
/// in plain sight.
struct OnboardingPINStep: View {
    let model: OnboardingModel

    @FocusState private var focused: Bool

    var body: some View {
        OnboardingStepScaffold(
            title: "Enter the robot's code",
            message: "Five characters, printed on the underside of the base. "
                + "Capitals matter, and it is not always digits.",
            back: { model.back() }
        ) {
            TextField("Code", text: Binding(get: { model.pinInput }, set: { model.pinInput = $0 }))
                .textFieldStyle(.roundedBorder)
                .font(.title3.monospaced())
                .autocorrectionDisabled()
                .focused($focused)
            #if os(iOS)
                // Deliberately not `.numberPad`: the code is the tail of a serial number
                // and can contain letters, and autocapitalising it would break a robot
                // whose code is lower-case.
                .keyboardType(.asciiCapable)
                .textInputAutocapitalization(.never)
            #endif
                .onChange(of: model.pinInput) { _, value in
                    if value.count > BLEPinSession.length {
                        model.pinInput = String(value.prefix(BLEPinSession.length))
                    }
                }
                .onSubmit(submit)
                .disabled(model.lockoutSeconds != nil)

            if let seconds = model.lockoutSeconds {
                Label(
                    "Too many wrong codes. The robot will accept another in \(seconds) s — "
                        + "reconnecting does not clear this.",
                    systemImage: "clock"
                )
                .font(.callout)
                .foregroundStyle(.orange)
                .fixedSize(horizontal: false, vertical: true)
            } else if model.attemptsBeforeLockout < BLEPinSession.freeAttempts {
                OnboardingErrorText(message: model.errorMessage)
                Text("\(model.attemptsBeforeLockout) attempts left before the robot starts making you wait.")
                    .font(.footnote)
                    .foregroundStyle(.secondary)
            } else {
                OnboardingErrorText(message: model.errorMessage)
            }
        } actions: {
            Button("Unlock") {
                submit()
            }
            .buttonStyle(.borderedProminent)
            .frame(maxWidth: .infinity)
            .disabled(!model.canSubmitPIN)
        }
        .onAppear { focused = true }
    }

    private func submit() {
        guard model.canSubmitPIN else { return }
        Task { await model.submitPIN() }
    }
}

