import CryptoKit
import Foundation
@testable import ReachyKit

/// A robot answering just enough of the GATT protocol to drive the onboarding flow. The
/// real service is Linux/BlueZ, so nothing simulates it — this replays the exchange.
///
/// Proxied commands answer on the read rather than acking and notifying: the pump's
/// two-phase path is covered in `ReachyKitTests`, and repeating it here would only make
/// these tests about the pump.
final class StubBLETransport: BLETransport, @unchecked Sendable {
    private let lock = NSLock()
    private var writes: [String] = []
    private var response = ""
    private var values: [BLECharacteristicID: String] = [:]
    private var notificationContinuation: AsyncStream<Data>.Continuation?
    private var eventContinuation: AsyncStream<BLETransportEvent>.Continuation?
    private var connects: [UUID] = []
    private var disconnects = 0

    var availability: BLEAvailability = .ready
    var discovered: [BLEPeripheralSnapshot] = []
    var maximumWriteLength = 512
    var attributeWriteLength = 512
    /// The code this robot accepts. Case-sensitive, like the real comparison.
    var pin = "4A7f9"
    var scanReply = #"["Home","Cafe"]"#
    /// What the network-status characteristic reads back once a sealed password has been
    /// accepted. Left nil, the robot never comes up — which is what a wrong Wi-Fi
    /// password looks like from here.
    var networkStatusAfterJoin: String?

    init(hardwareID: String = "a1b2c3d4e5f60718", networkStatus: String = "HOTSPOT [wlan0] 10.42.0.1") {
        values[.hardwareID] = hardwareID
        values[.networkStatus] = networkStatus
    }

    var writtenCommands: [String] {
        lock.withLock { writes }
    }

    var connectedIDs: [UUID] {
        lock.withLock { connects }
    }

    var disconnectCount: Int {
        lock.withLock { disconnects }
    }

    func advertise(_ peripherals: [BLEPeripheralSnapshot]) {
        discovered = peripherals
        lock.withLock { eventContinuation }?.yield(.discoveredChanged(peripherals))
    }

    func startScan() throws {}

    func stopScan() {}

    func connect(_ id: UUID) async throws {
        lock.withLock { connects.append(id) }
    }

    func disconnect() {
        lock.withLock { disconnects += 1 }
    }

    func setNotify(_: Bool, for _: BLECharacteristicID) async throws {}

    func write(_ payload: Data, to _: BLECharacteristicID) async throws {
        let command = String(decoding: payload, as: UTF8.self)
        lock.withLock {
            writes.append(command)
            response = reply(to: command)
        }
    }

    func read(_ characteristic: BLECharacteristicID) async throws -> Data {
        try lock.withLock {
            let text = characteristic == .response ? response : values[characteristic]
            guard let text else { throw BLETransportError.characteristicMissing(characteristic) }
            return Data(text.utf8)
        }
    }

    func notifications() -> AsyncStream<Data> {
        let (stream, continuation) = AsyncStream.makeStream(of: Data.self)
        lock.withLock { notificationContinuation = continuation }
        return stream
    }

    func events() -> AsyncStream<BLETransportEvent> {
        let (stream, continuation) = AsyncStream.makeStream(of: BLETransportEvent.self)
        lock.withLock { eventContinuation = continuation }
        return stream
    }

    /// Called under `lock`.
    private func reply(to command: String) -> String {
        if command == "PING" {
            return "PONG"
        }
        if let code = command.dropPrefixIfPresent("PIN_") {
            return code == pin ? "OK: Authenticated" : "ERROR: Incorrect PIN"
        }
        if command == "WIFI_KEYEX" {
            let key = Curve25519.KeyAgreement.PrivateKey().publicKey.rawRepresentation.base64EncodedString()
            return #"{"kid":"k1","pk":"\#(key)","alg":"\#(WiFiProvisioningKey.supportedAlgorithm)"}"#
        }
        if command == "WIFI_SCAN" {
            return scanReply
        }
        if command.hasPrefix("WIFI_CONNECT_ENC ") {
            if let joined = networkStatusAfterJoin {
                values[.networkStatus] = joined
            }
            return "OK: Connecting"
        }
        return "ECHO: \(command)"
    }
}

private extension String {
    func dropPrefixIfPresent(_ prefix: String) -> String? {
        hasPrefix(prefix) ? String(dropFirst(prefix.count)) : nil
    }
}

import Foundation
@testable import ReachyKit
@testable import ReachyUI
import Testing

/// The flow's job is to get a robot from "no network at all" onto one, and then to hand
/// it over by identity — it is provisioned at one address and turns up at another.
///
/// `finish()` and `cancel()` also write to `UserDefaults`, which these tests deliberately
/// do not assert on: it is process-global state and `--parallel` runs suites at the same
/// time. What the caller actually acts on is the returned outcome.
@MainActor
@Suite("Onboarding flow", .timeLimit(.minutes(1)))
struct OnboardingModelTests {
    /// Generous on the deadline, tiny on the interval: the stub reports the join on the
    /// first poll, so nothing here waits out a duration.
    private static let patient = configuration(timeout: .seconds(10))
    /// Short enough that giving up is the thing being tested rather than a slow runner.
    private static let impatient = configuration(timeout: .milliseconds(200))

    private static func configuration(timeout: Duration) -> BLEProvisioningSession.Configuration {
        var configuration = BLEProvisioningSession.Configuration()
        configuration.joinTimeout = timeout
        configuration.joinPollInterval = .milliseconds(10)
        return configuration
    }

    private func makeModel(
        _ transport: StubBLETransport,
        configuration: BLEProvisioningSession.Configuration = OnboardingModelTests.patient
    ) -> OnboardingModel {
        OnboardingModel { BLEProvisioningSession(transport: transport, configuration: configuration) }
    }

    /// Walks up to the network step, which is where most of the interesting choices are.
    private func unlockedModel(
        _ transport: StubBLETransport,
        configuration: BLEProvisioningSession.Configuration = OnboardingModelTests.patient
    ) async -> OnboardingModel {
        let model = makeModel(transport, configuration: configuration)
        model.beginScan()
        await model.connect(to: UUID())
        model.pinInput = transport.pin
        await model.submitPIN()
        return model
    }

    @Test("no Bluetooth session exists until the welcome screen has been left")
    func buildsTheSessionLate() {
        let model = makeModel(StubBLETransport())

        #expect(model.session == nil)
        #expect(model.availability == .unknown)

        model.beginScan()

        #expect(model.session != nil)
        #expect(model.step == .scan)
    }

    @Test("a wrong code stays put and reports how many tries are left")
    func countsDownFreeAttempts() async {
        let transport = StubBLETransport()
        let model = makeModel(transport)
        model.beginScan()
        await model.connect(to: UUID())
        #expect(model.step == .pin)

        model.pinInput = "00000"
        await model.submitPIN()

        #expect(model.step == .pin)
        #expect(model.attemptsBeforeLockout == BLEPinSession.freeAttempts - 1)
        #expect(model.errorMessage != nil)
    }

    @Test("the right code opens the network step and asks the robot what it can see")
    func loadsNetworksAfterUnlocking() async {
        let transport = StubBLETransport()

        let model = await unlockedModel(transport)

        #expect(model.step == .network)
        #expect(model.networks == ["Home", "Cafe"])
        #expect(model.selectedSSID == "Home")
    }

    @Test("\"Other network…\" sends the name that was typed, not one off the truncated list")
    func sealsTheManuallyTypedNetwork() async {
        let transport = StubBLETransport()
        transport.networkStatusAfterJoin = "CONNECTED [wlan0] 192.168.1.42"
        let model = await unlockedModel(transport)

        model.selectedSSID = nil
        model.manualSSID = "Guest Wi-Fi"
        model.password = "REDACTED"
        await model.join()

        let sealed = transport.writtenCommands.first { $0.hasPrefix("WIFI_CONNECT_ENC ") }
        #expect(sealed?.contains(#""ssid":"Guest Wi-Fi""#) == true)
        // The password is what the sealing exists to hide; it must never appear as itself.
        #expect(sealed?.contains("REDACTED") == false)
    }

    @Test("a robot that never comes up gives up and keeps the password for another try")
    func keepsThePasswordAfterGivingUp() async {
        let transport = StubBLETransport()
        let model = await unlockedModel(transport, configuration: Self.impatient)

        model.password = "REDACTED"
        await model.join()

        #expect(model.joinState == .gaveUp)
        #expect(model.password == "REDACTED")

        model.editNetwork()

        #expect(model.step == .network)
    }

    @Test("a successful join carries the robot's new address into the handoff")
    func handsOverIdentityAndAddress() async {
        let transport = StubBLETransport(hardwareID: "a1b2c3d4e5f60718")
        transport.networkStatusAfterJoin = "CONNECTED [wlan0] 192.168.1.42"
        let model = await unlockedModel(transport)

        model.password = "REDACTED"
        await model.join()

        #expect(model.joinState == .joined)
        // Cleared as soon as it is no longer needed: ADR 0001 leaves storing credentials
        // to a real pairing protocol.
        #expect(model.password.isEmpty)

        model.continueAfterJoin()
        #expect(model.step == .handoff)

        let outcome = model.finish()

        #expect(outcome.hardwareID == "a1b2c3d4e5f60718")
        #expect(outcome.address == RobotAddress(parsing: "192.168.1.42"))
    }

    @Test("a robot already on a network has nothing left to configure")
    func skipsAJoinThatAlreadyHappened() async {
        let transport = StubBLETransport(networkStatus: "CONNECTED [wlan0] 192.168.1.7")

        let model = await unlockedModel(transport)

        #expect(model.isAlreadyOnNetwork)

        model.skipNetwork()

        #expect(model.step == .handoff)
        #expect(model.finish().address == RobotAddress(parsing: "192.168.1.7"))
    }

    @Test("stepping back from the code screen drops the link the code belonged to")
    func dropsTheLinkOnTheWayBack() async {
        let transport = StubBLETransport()
        let model = makeModel(transport)
        model.beginScan()
        await model.connect(to: UUID())

        model.back()

        #expect(model.step == .scan)
        #expect(transport.disconnectCount == 1)
    }
}

