/// the scripts that put it back on a network.
///
/// It scans and unlocks on its own rather than borrowing a `RobotSession`, because the
/// robot it exists for is by definition one no `RobotSession` can reach.
@MainActor
@Observable
final class BLEConsoleModel {
    /// The robot's buffer fills at the daemon's own pace, so an empty reply means nothing
    /// happened rather than that we should ask harder.
    private static let activePoll: Duration = .milliseconds(500)
    private static let idlePoll: Duration = .milliseconds(1500)

    enum Stage: Equatable {
        case scanning
        case connecting
        /// Linked. The journal reads without the code; the scripts do not.
        case locked
        case unlocked
    }

    private(set) var stage: Stage = .scanning
    private(set) var scripts: [BLERecoveryScript] = []
    private(set) var isBusy = false
    private(set) var errorMessage: String?
    /// Set when the journal feed itself stopped, which the console has to say out loud —
    /// a frozen tail otherwise reads as a quiet robot.
    private(set) var journalFailure: String?
    let log = LogConsoleModel()

    var pinInput = ""

    private let link: BLELink
    private var journalTask: Task<Void, Never>?
    /// Held while a script is being dispatched. The pump serialises anyway; this only
    /// keeps a queued poll from sitting in front of the write.
    private var suspended = false

    init(link: (@MainActor () -> BLELink)? = nil) {
        self.link = link?() ?? BLELink()
    }

    // MARK: - Derived state

    var availability: BLEAvailability { link.availability }
    var discovered: [BLEPeripheralSnapshot] { link.discovered }
    var hardwareID: String? { link.hardwareID }
    var attemptsBeforeLockout: Int { link.pin.attemptsBeforeLockout }

    var canSubmitPIN: Bool {
        !isBusy && pinInput.count == BLEPinSession.length
    }

    // MARK: - Link

    func startScan() {
        stage = .scanning
        errorMessage = nil
        if !link.startScan() {
            errorMessage = link.lastError
        }
    }

    func connect(to id: UUID) async {
        stage = .connecting
        isBusy = true
        errorMessage = nil
        defer { isBusy = false }
        guard await link.connect(to: id) else {
            errorMessage = link.lastError
            stage = .scanning
            return
        }
        link.stopScan()
        stage = .locked
        // The journal needs no code, and a robot too broken to unlock is exactly the one
        // whose log is worth reading.
        startJournal()
    }

    @discardableResult
    func submitPIN() async -> Bool {
        isBusy = true
        errorMessage = nil
        defer { isBusy = false }
        guard await link.authenticate(pinInput) else {
            errorMessage = link.lastError
            return false
        }
        pinInput = ""
        stage = .unlocked
        scripts = await link.availableScripts()
        return true
    }

    // MARK: - Scripts

    /// Dispatches a script and drops back to locked, because the robot clears its own
    /// session on any `CMD_*` whether the script worked or not.
    func run(_ script: BLERecoveryScript) async {
        suspended = true
        defer { suspended = false }
        log.ingest("--- dispatched \(script.name) ---")
        await link.run(script)
        stage = .locked
    }

    /// Re-sends the code immediately before dispatching, so a session opened five minutes
    /// ago for something harmless cannot carry a destructive script through with it.
    func runGuarded(_ script: BLERecoveryScript, code: String) async -> Bool {
        pinInput = code
        guard await submitPIN() else { return false }
        await run(script)
        return true
    }

    func stop() {
        journalTask?.cancel()
        journalTask = nil
        pinInput = ""
        Task { [link] in await link.stopJournal() }
        link.stop()
    }

    /// Polls the journal until the screen goes away.
    ///
    /// The robot hands back a slice of its buffer cut wherever the window fell and empties
    /// what it hands over, so the reader carries the partial tail between polls and the
    /// console only ever sees whole lines.
    private func startJournal() {
        journalTask?.cancel()
        journalTask = Task { [weak self] in
            guard let self, await link.startJournal() else {
                self?.journalFailure = self?.link.lastError
                return
            }
            var reader = BLEJournalReader()
            var interval = Self.activePoll
            while !Task.isCancelled {
                try? await Task.sleep(for: interval)
                guard !Task.isCancelled else { return }
                if suspended { continue }
                guard let chunk = await link.readJournal() else {
                    journalFailure = link.lastError
                    return
                }
                let lines = reader.ingest(chunk)
                interval = lines.isEmpty ? Self.idlePoll : Self.activePoll
                guard !lines.isEmpty else { continue }
                log.ingest(lines.joined(separator: "\n"))
            }
        }
    }
}

import ReachyKit
import SwiftUI

/// The way back in when the network is not an option: a Bluetooth link to the robot, its
/// journal, and the scripts that undo whatever took it off the air.
struct BLEConsoleScreen: View {
    @State private var model = BLEConsoleModel()
    @State private var showsCommands = false

    var body: some View {
        Group {
            switch model.stage {
            case .scanning, .connecting:
                linkSetup
            case .locked, .unlocked:
                journal
            }
        }
        .navigationTitle("Recovery")
        .onAppear { model.startScan() }
        .onDisappear { model.stop() }
    }

    // MARK: - Getting a link

    private var linkSetup: some View {
        Form {
            Section("Robot") {
                switch model.availability {
                case .ready, .unknown:
                    if model.discovered.isEmpty {
                        HStack(spacing: 10) {
                            ProgressView()
                            Text("Searching over Bluetooth…").foregroundStyle(.secondary)
                        }
                    }
                    ForEach(model.discovered) { robot in
                        Button {
                            Task { await model.connect(to: robot.id) }
                        } label: {
                            LabeledContent(robot.name) {
                                Text("\(robot.rssi) dBm").font(.caption.monospaced())
                            }
                        }
                        .disabled(model.isBusy)
                    }
                case .poweredOff:
                    Label("Bluetooth is switched off.", systemImage: "antenna.radiowaves.left.and.right.slash")
                case .unauthorized:
                    Label("This app can't use Bluetooth.", systemImage: "hand.raised")
                case .unsupported:
                    Label("This device has no Bluetooth.", systemImage: "antenna.radiowaves.left.and.right.slash")
                }
            } footer: {
                Text("Robots all advertise the same name, so they are listed by signal strength.")
            }
            if let error = model.errorMessage {
                Section {
                    Text(error).font(.callout).foregroundStyle(.red)
                }
            }
        }
        .formStyle(.grouped)
    }

    // MARK: - Linked

    private var journal: some View {
        LogConsoleView(
            model: model.log,
            source: model.hardwareID ?? "bluetooth",
            emptyDescription: "The robot sends its daemon journal a slice at a time. "
                + "Nothing has arrived yet.",
            failure: model.journalFailure
        )
        .safeAreaInset(edge: .top) { lossWarning }
        .toolbar {
            ToolbarItem {
                Button {
                    showsCommands = true
                } label: {
                    Label("Commands", systemImage: "wrench.and.screwdriver")
                }
            }
        }
        .sheet(isPresented: $showsCommands) {
            NavigationStack {
                BLERecoveryCommandsSheet(model: model)
                    .toolbar {
                        ToolbarItem(placement: .cancellationAction) {
                            Button("Done") { showsCommands = false }
                        }
                    }
            }
        }
    }

    /// Not a footnote. The robot slices its buffer well past what one Bluetooth read can
    /// carry and throws away what it handed over, so lines genuinely disappear here and
    /// nowhere else.
    private var lossWarning: some View {
        Label(
            "Bluetooth drops journal lines when the robot logs faster than this can read. "
                + "Once the robot is on the network, the Diagnostics console is the complete one.",
            systemImage: "exclamationmark.triangle"
        )
        .font(.caption)
        .foregroundStyle(.orange)
        .padding(.horizontal)
        .padding(.vertical, 6)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(.bar)
    }
}

import ReachyKit
import SwiftUI

/// The scripts the robot actually has, grouped by what they cost.
///
/// The destructive one is not in the list. It sits behind a collapsed group that leads to
/// its own screen, because a row a thumb can reach by accident is the wrong place for
/// something that erases the robot's software.
struct BLERecoveryCommandsSheet: View {
    let model: BLEConsoleModel

    @State private var confirming: BLERecoveryScript?

    var body: some View {
        Form {
            if model.stage == .locked {
                unlock
            } else {
                commands
            }
        }
        .formStyle(.grouped)
        .navigationTitle("Recovery")
        .confirmationDialog(
            confirming?.name ?? "",
            isPresented: Binding(get: { confirming != nil }, set: { if !$0 { confirming = nil } }),
            presenting: confirming
        ) { script in
            Button("Run \(script.name)", role: .destructive) {
                Task { await model.run(script) }
            }
        } message: { script in
            Text(script.summary)
        }
    }

    private var unlock: some View {
        Section("Unlock") {
            TextField("Code", text: Binding(get: { model.pinInput }, set: { model.pinInput = $0 }))
                .font(.body.monospaced())
                .autocorrectionDisabled()
            #if os(iOS)
                .keyboardType(.asciiCapable)
                .textInputAutocapitalization(.never)
            #endif
            Button("Unlock") {
                Task { await model.submitPIN() }
            }
            .disabled(!model.canSubmitPIN)
            if let error = model.errorMessage {
                Text(error).font(.callout).foregroundStyle(.red)
            }
        } footer: {
            Text("The five characters from the robot's base. Running any script clears the robot's session, "
                + "so the code is needed again each time — that is the robot's rule, not this app's.")
        }
    }

    @ViewBuilder
    private var commands: some View {
        let ordinary = model.scripts.filter { $0.severity != .destructive }
        let destructive = model.scripts.filter { $0.severity == .destructive }

        Section("Commands") {
            if ordinary.isEmpty {
                Text("This robot reports no recovery scripts.")
                    .foregroundStyle(.secondary)
            }
            ForEach(ordinary) { script in
                Button {
                    confirming = script
                } label: {
                    BLERecoveryScriptRow(script: script)
                }
            }
        } footer: {
            Text("A script answers nothing — the robot's handler crashes encoding its own reply. "
                + "Watch the journal for what happened.")
        }

        if !destructive.isEmpty {
            Section {
                DisclosureGroup("Destructive recovery") {
                    ForEach(destructive) { script in
                        NavigationLink {
                            BLESoftwareResetScreen(model: model, script: script)
                        } label: {
                            BLERecoveryScriptRow(script: script)
                        }
                    }
                }
            }
        }
    }
}

struct BLERecoveryScriptRow: View {
    let script: BLERecoveryScript

    var body: some View {
        Label {
            VStack(alignment: .leading, spacing: 2) {
                Text(script.name)
                    .font(.body.monospaced())
                Text(script.summary)
                    .font(.footnote)
                    .foregroundStyle(.secondary)
            }
        } icon: {
            Image(systemName: icon)
                .foregroundStyle(tint)
        }
        .fixedSize(horizontal: false, vertical: true)
    }

    private var icon: String {
        switch script.severity {
        case .routine: "arrow.clockwise"
        case .disruptive: "exclamationmark.triangle"
        case .destructive: "trash"
        }
    }

    private var tint: Color {
        switch script.severity {
        case .routine: .secondary
        case .disruptive: .orange
        case .destructive: .red
        }
    }
}

